function uid(p) { return p + "_" + Math.random().toString(36).slice(2, 9); }
function todayStr() { const d = new Date(); return d.toISOString().slice(0, 10); }
function nowTime() { const d = new Date(); return d.toTimeString().slice(0, 5); }
function cleanPhone(p) { return (p || "").replace(/[^\d]/g, ""); }
function waLink(phone, text) { return `https://wa.me/${cleanPhone(phone)}?text=${encodeURIComponent(text)}`; }
function mailLink(email, subject, body) { return `mailto:${email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`; }
function mapsLink(direccion) { return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(direccion)}`; }
function mapsLinkCoord(coord) { return `https://www.google.com/maps/search/?api=1&query=${coord.lat},${coord.lng}`; }
function diffHours(start, end) {
  if (!start || !end) return 0;
  const [sh, sm] = start.split(":").map(Number);
  const [eh, em] = end.split(":").map(Number);
  const mins = (eh * 60 + em) - (sh * 60 + sm);
  return mins > 0 ? mins / 60 : 0;
}
function fmtHM(hours) {
  const totalMin = Math.round(hours * 60);
  const h = Math.floor(totalMin / 60);
  const m = totalMin % 60;
  return `${h}h ${m}m`;
}
function fechaEs(iso) {
  if (!iso) return "";
  const [y, m, d] = iso.split("-");
  return `${d}/${m}/${y}`;
}
function eur(n) {
  return new Intl.NumberFormat("es-ES", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(n || 0);
}
function addDaysStr(dateStr, days) {
  const d = new Date(dateStr + "T00:00:00");
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}
function esFinde(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  const dow = d.getDay();
  return dow === 0 || dow === 6;
}
function calcularDiasObra(obra, festivos) {
  if (!obra.fechaInicioPlan || !obra.diasEstimados || obra.diasEstimados <= 0) return [];
  const dias = [];
  let cursor = obra.fechaInicioPlan;
  let guard = 0;
  while (dias.length < obra.diasEstimados && guard < 3650) {
    guard++;
    if (!esFinde(cursor) && !(festivos && festivos[cursor])) {
      dias.push(cursor);
    }
    cursor = addDaysStr(cursor, 1);
  }
  return dias;
}
function festivoAfectaObras(data, dateStr) {
  if (esFinde(dateStr)) return [];
  return data.clients.filter(c => c.tipo === "obra" && c.fechaInicioPlan && c.diasEstimados > 0)
    .filter(c => calcularDiasObra(c, data.festivos || {}).includes(dateStr));
}
