  const [adminRole, setAdminRole] = useState(null); // null | "admin1" | "admin2"
  const [pinPrompt, setPinPrompt] = useState(false);
  const [pinValue, setPinValue] = useState("");
  const [pinError, setPinError] = useState("");
  const [deviceWorkerId, setDeviceWorkerId] = useState(undefined); // undefined=cargando, null=sin asignar, "__admin__"=solo admin, o id de trabajador

  useEffect(() => { loadData().then(d => { setData(d); setLoading(false); }); }, []);
  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get(DEVICE_KEY, false);
        setDeviceWorkerId(res && res.value ? res.value : null);
      } catch (e) { setDeviceWorkerId(null); }
    })();
  }, []);

  const asignarDispositivo = async (workerId) => {
    setDeviceWorkerId(workerId);
    try { await window.storage.set(DEVICE_KEY, workerId, false); } catch (e) {}
  };
  const reasignarDispositivo = async () => {
    setDeviceWorkerId(null);
    try { await window.storage.delete(DEVICE_KEY, false); } catch (e) {}
  };

  const [consentGiven, setConsentGiven] = useState(undefined); // undefined=cargando, null=no dado, true=aceptado
