function allStopsToday(data) {
  const today = todayStr();
  const list = [];
  data.orders.filter(o => o.fecha === today).forEach(o => {
    o.stops.forEach((s, idx) => list.push({ order: o, stop: s, idx }));
  });
  return list;
}

function PanelView({ data, persist, getClient, getWorker, adminMode }) {
  const stops = allStopsToday(data);
  const pendientes = stops.filter(s => s.stop.estado === "pendiente").length;
  const enProgreso = stops.filter(s => s.stop.estado === "en_progreso").length;
  const completados = stops.filter(s => s.stop.estado === "completado");
  const pendientesAviso = completados.filter(s => !s.stop.notificado);
  const avisados = completados.filter(s => s.stop.notificado);
  const horasPersonaHoy = completados.reduce((acc, s) => acc + diffHours(s.stop.horaInicio, s.stop.horaFin) * (s.stop.crewSize || s.order.workerIds.length), 0);
  const avisosAlmuerzo = data.orders.filter(o => o.fecha === todayStr() && (o.avisoTiempoAlmuerzo || o.avisoUbicacionAlmuerzo));

  const notificar = (orderId, clienteId, canal) => {
    const next = structuredClone(data);
    const order = next.orders.find(o => o.id === orderId);
    const stop = order.stops.find(s => s.clienteId === clienteId);
    stop.notificado = true;
    persist(next);
  };

  const resetAll = () => {
    if (!confirm("Esto borra todos los datos actuales y vuelve a cargar los datos de ejemplo. ¿Continuar?")) return;
    persist(seedData());
  };

  return (
    <div>
      <div className="gj-grid2" style={{ marginBottom: 12 }}>
        <div className="gj-stat"><div className="n">{pendientes + enProgreso}</div><div className="l">Mantenimientos por hacer hoy</div></div>
        <div className="gj-stat"><div className="n">{fmtHM(horasPersonaHoy)}</div><div className="l">Horas-persona invertidas hoy</div></div>
      </div>

      {adminMode && avisosAlmuerzo.length > 0 && (
        <>
          <h3 className="gj-h3">Avisos de almuerzo de hoy</h3>
          {avisosAlmuerzo.map(o => {
            const crew = o.workerIds.map(id => getWorker(id)?.nombre).filter(Boolean).join(", ");
            return (
              <div className="gj-card" key={o.id} style={{ background: "var(--warn-bg)" }}>
                <div style={{ fontWeight: 600 }}>{crew}</div>
                <div style={{ fontSize: 12.5, marginTop: 2 }}>{o.almuerzoInicio} – {o.almuerzoFin}</div>
                <div style={{ display: "flex", gap: 10, marginTop: 2 }}>
                  {o.almuerzoInicioCoord ? (
                    <a href={mapsLinkCoord(o.almuerzoInicioCoord)} target="_blank" rel="noreferrer" style={{ fontSize: 11.5 }}>📍 Ver inicio</a>
                  ) : <span style={{ fontSize: 11.5, color: "var(--warn)" }}>Sin ubicación de inicio</span>}
                  {o.almuerzoFinCoord ? (
                    <a href={mapsLinkCoord(o.almuerzoFinCoord)} target="_blank" rel="noreferrer" style={{ fontSize: 11.5 }}>📍 Ver fin</a>
                  ) : <span style={{ fontSize: 11.5, color: "var(--warn)" }}>Sin ubicación de fin</span>}
                </div>
                <div style={{ display: "flex", gap: 4, flexWrap: "wrap", marginTop: 4 }}>
                  {o.avisoTiempoAlmuerzo && <span className="gj-badge no_hecho">Tiempo superado en más de 20 min</span>}
                  {o.avisoUbicacionAlmuerzo && <span className="gj-badge no_hecho">Ubicación no coincide con ningún cliente de la ruta</span>}
                </div>
              </div>
            );
          })}
        </>
      )}

      <h3 className="gj-h3">Mantenimientos completados hoy, pendientes de avisar</h3>
      {pendientesAviso.length === 0 && <div className="gj-card gj-empty">No hay mantenimientos pendientes de avisar.</div>}
      {pendientesAviso.map(({ order, stop }) => {
        const cliente = getClient(stop.clienteId);
        const crew = order.workerIds.map(id => getWorker(id)?.nombre).filter(Boolean).join(", ");
        const dur = diffHours(stop.horaInicio, stop.horaFin);
        const laboresTxt = (stop.labores && stop.labores.length > 0) ? ` Trabajos realizados: ${stop.labores.join(", ")}.` : "";
        const msg = `Jardinería Belardi le informa que el mantenimiento de su parcela ha sido ejecutado hoy por ${crew}.${laboresTxt}`;
        return (
          <div className="gj-card" key={cliente.id + stop.horaInicio}>
            <div className="gj-row">
              <div>
                <div style={{ fontWeight: 600 }}>{cliente.nombre}</div>
                <div style={{ fontSize: 12, color: "var(--ink-soft)" }}>{stop.horaInicio}–{stop.horaFin} · {fmtHM(dur)} · cuadrilla: {crew}</div>
                {stop.labores && stop.labores.length > 0 && <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginTop: 2 }}>Trabajos: {stop.labores.join(", ")}</div>}
              </div>
            </div>
            <div className="gj-row" style={{ marginTop: 8, gap: 6 }}>
              <a className="gj-btn accent" style={{ flex: 1, justifyContent: "center" }} href={waLink(cliente.telefono, msg)} target="_blank" rel="noreferrer" onClick={() => notificar(order.id, cliente.id, "wa")}>
                <Send size={13} /> WhatsApp
              </a>
              <a className="gj-btn" style={{ flex: 1, justifyContent: "center" }} href={mailLink(cliente.email, "Mantenimiento realizado", msg)} onClick={() => notificar(order.id, cliente.id, "mail")}>
                <Mail size={13} /> Correo
              </a>
            </div>
          </div>
        );
      })}

      <h3 className="gj-h3" style={{ marginTop: 12 }}>Mantenimientos avisados</h3>
      {avisados.length === 0 && <div className="gj-card gj-empty">Todavía no se ha avisado a ningún cliente hoy.</div>}
      {avisados.map(({ order, stop }) => {
        const cliente = getClient(stop.clienteId);
        const crew = order.workerIds.map(id => getWorker(id)?.nombre).filter(Boolean).join(", ");
        const dur = diffHours(stop.horaInicio, stop.horaFin);
        return (
          <div className="gj-card" key={cliente.id + stop.horaInicio} style={{ opacity: 0.75 }}>
            <div className="gj-row">
              <div>
                <div style={{ fontWeight: 600 }}>{cliente.nombre}</div>
                <div style={{ fontSize: 12, color: "var(--ink-soft)" }}>{stop.horaInicio}–{stop.horaFin} · {fmtHM(dur)} · cuadrilla: {crew}</div>
                {stop.labores && stop.labores.length > 0 && <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginTop: 2 }}>Trabajos: {stop.labores.join(", ")}</div>}
              </div>
              <span className="gj-badge completado">Avisado</span>
            </div>
          </div>
        );
      })}

      <hr className="gj-divider" />
      <button className="gj-btn ghost" onClick={resetAll}><RotateCcw size={13} /> Restablecer datos de ejemplo</button>
    </div>
  );
}

function ClientesView({ data, persist, setView, setFocusClienteId }) {
  const [showImportes, setShowImportes] = useState(false);
  const [editing, setEditing] = useState(null);
  const [busqueda, setBusqueda] = useState("");

  const blank = { id: "", nombre: "", direccion: "", telefono: "", email: "", tipo: "mantenimiento", cuotaMensual: "", presupuesto: "", estadoObra: "en_curso", personasEstimadas: "", diasEstimados: "", fechaInicioPlan: "", orden: 0, activo: true };

  const save = (form) => {
    const next = structuredClone(data);
    const clean = {
      ...form,
      cuotaMensual: Number(form.cuotaMensual) || 0,
      presupuesto: Number(form.presupuesto) || 0,
      personasEstimadas: Number(form.personasEstimadas) || 0,
      diasEstimados: Number(form.diasEstimados) || 0,
    };
    if (form.id) {
      const i = next.clients.findIndex(c => c.id === form.id);
      next.clients[i] = clean;
    } else {
      const maxOrden = Math.max(0, ...next.clients.filter(c => c.tipo === "obra").map(c => c.orden || 0));
      next.clients.push({ ...clean, id: uid("cli"), orden: maxOrden + 1 });
    }
    persist(next);
    setEditing(null);
  };

  const remove = (id) => {
    if (!confirm("¿Eliminar este cliente? También se perderá su histórico visible en calendario y rentabilidad.")) return;
    const next = structuredClone(data);
    next.clients = next.clients.filter(c => c.id !== id);
    persist(next);
  };

  const filtroTexto = busqueda.trim().toLowerCase();
  const coincide = (c) => !filtroTexto || c.nombre.toLowerCase().includes(filtroTexto);
  const mantenimiento = data.clients.filter(c => c.tipo !== "obra" && coincide(c));
  const obras = data.clients.filter(c => c.tipo === "obra" && coincide(c));

  const renderCliente = (c) => (
    <div className="gj-card" key={c.id}>
      <div className="gj-row">
        <div>
          <div style={{ fontWeight: 600 }}>{c.nombre}</div>
          <div style={{ fontSize: 12, color: "var(--ink-soft)", display: "flex", alignItems: "center", gap: 4 }}>
            {c.direccion}
            <a href={mapsLink(c.direccion)} target="_blank" rel="noreferrer" title="Ver en el mapa" onClick={e => e.stopPropagation()}>
              <MapPin size={13} color="var(--accent)" />
            </a>
          </div>
          <div style={{ fontSize: 12, color: "var(--ink-soft)" }}>{c.telefono}{c.email ? " · " + c.email : ""}</div>
          {showImportes && c.tipo === "obra" && (
            <div style={{ fontSize: 12.5, marginTop: 4, fontWeight: 600 }}>
              {eur(c.presupuesto)} · {c.estadoObra === "finalizada" ? "Finalizada" : "En curso"}
            </div>
          )}
          {showImportes && c.tipo !== "obra" && <div style={{ fontSize: 12.5, marginTop: 4, fontWeight: 600 }}>{eur(c.cuotaMensual)}/mes</div>}
        </div>
        <div style={{ display: "flex", gap: 2 }}>
          <button className="gj-btn ghost" onClick={() => { setFocusClienteId(c.id); setView("mapa"); }} title="Ver en el mapa de la app"><Map size={14} color="var(--primary)" /></button>
          <button className="gj-btn ghost" onClick={() => setEditing(c)}><Pencil size={14} /></button>
          <button className="gj-btn ghost" onClick={() => remove(c.id)}><Trash2 size={14} color="var(--warn)" /></button>
        </div>
      </div>
    </div>
  );

  return (
    <div>
      <div className="gj-row" style={{ marginBottom: 10 }}>
        <h2 className="gj-h2" style={{ margin: 0 }}>Clientes</h2>
        <button className="gj-btn primary" onClick={() => setEditing(blank)}><Plus size={14} /> Añadir</button>
      </div>

      <div className="gj-field">
        <input className="gj-input" value={busqueda} onChange={e => setBusqueda(e.target.value)} placeholder="Buscar cliente por nombre..." />
      </div>

      <label className="gj-row" style={{ marginBottom: 10, cursor: "pointer" }}>
        <span style={{ fontSize: 12.5, color: "var(--ink-soft)" }}>Mostrar importes (cuota / presupuesto), ocultos por defecto</span>
        <input type="checkbox" checked={showImportes} onChange={e => setShowImportes(e.target.checked)} />
      </label>

      {editing && <ClienteForm initial={editing} onCancel={() => setEditing(null)} onSave={save} />}

      <h3 className="gj-h3">Clientes de mantenimiento</h3>
      {mantenimiento.length === 0 && <div className="gj-card gj-empty">{filtroTexto ? "Ningún cliente de mantenimiento coincide con la búsqueda." : "Todavía no hay clientes de mantenimiento."}</div>}
      {mantenimiento.map(renderCliente)}

      <h3 className="gj-h3" style={{ marginTop: 8 }}>Clientes de obras</h3>
      {obras.length === 0 && <div className="gj-card gj-empty">{filtroTexto ? "Ninguna obra coincide con la búsqueda." : "Todavía no hay clientes de obras."}</div>}
      {obras.map(renderCliente)}
    </div>
  );
}

function ClienteForm({ initial, onCancel, onSave }) {
  const [form, setForm] = useState(initial);
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));
  const [err, setErr] = useState("");
  const submit = () => {
    if (!form.nombre.trim() || !form.direccion.trim() || !form.telefono.trim()) {
      setErr("Rellena al menos nombre, dirección y teléfono.");
      return;
    }
    onSave(form);
  };
  return (
    <div className="gj-card">
      <div className="gj-field"><label className="gj-label">Tipo de cliente</label>
        <select className="gj-select" value={form.tipo} onChange={e => set("tipo", e.target.value)}>
          <option value="mantenimiento">Mantenimiento (recurrente)</option>
          <option value="obra">Obra (trabajo puntual)</option>
        </select>
      </div>
      <div className="gj-field"><label className="gj-label">Nombre</label><input className="gj-input" value={form.nombre} onChange={e => set("nombre", e.target.value)} placeholder="Familia Pérez" /></div>
      <div className="gj-field"><label className="gj-label">Dirección</label><input className="gj-input" value={form.direccion} onChange={e => set("direccion", e.target.value)} placeholder="Calle Mayor 3, Madrid" /></div>
      <div className="gj-grid2">
        <div className="gj-field"><label className="gj-label">Teléfono (con prefijo)</label><input className="gj-input" value={form.telefono} onChange={e => set("telefono", e.target.value)} placeholder="34600111222" /></div>
        <div className="gj-field"><label className="gj-label">Email (opcional)</label><input className="gj-input" value={form.email} onChange={e => set("email", e.target.value)} placeholder="cliente@correo.com" /></div>
      </div>
      {form.tipo === "obra" ? (
        <div>
          <div className="gj-grid2">
            <div className="gj-field"><label className="gj-label">Presupuesto de la obra (€)</label><input className="gj-input" type="number" value={form.presupuesto} onChange={e => set("presupuesto", e.target.value)} placeholder="3000" /></div>
            <div className="gj-field"><label className="gj-label">Estado</label>
              <select className="gj-select" value={form.estadoObra} onChange={e => set("estadoObra", e.target.value)}>
                <option value="en_curso">En curso</option>
                <option value="finalizada">Finalizada</option>
              </select>
            </div>
          </div>
          <div className="gj-grid2">
            <div className="gj-field"><label className="gj-label">Personas estimadas</label><input className="gj-input" type="number" value={form.personasEstimadas || ""} onChange={e => set("personasEstimadas", e.target.value)} placeholder="2" /></div>
            <div className="gj-field"><label className="gj-label">Días estimados</label><input className="gj-input" type="number" value={form.diasEstimados || ""} onChange={e => set("diasEstimados", e.target.value)} placeholder="4" /></div>
          </div>
          <div className="gj-field"><label className="gj-label">Fecha de inicio prevista</label><input className="gj-input" type="date" value={form.fechaInicioPlan || ""} onChange={e => set("fechaInicioPlan", e.target.value)} /></div>
        </div>
      ) : (
        <div className="gj-field"><label className="gj-label">Cuota mensual (€)</label><input className="gj-input" type="number" value={form.cuotaMensual} onChange={e => set("cuotaMensual", e.target.value)} placeholder="100" /></div>
      )}
      {err && <div style={{ color: "var(--warn)", fontSize: 12.5, marginBottom: 8 }}>{err}</div>}
      <div className="gj-row" style={{ gap: 6 }}>
        <button className="gj-btn block" onClick={onCancel}>Cancelar</button>
        <button className="gj-btn primary block" onClick={submit}>Guardar</button>
      </div>
    </div>
  );
}

function EquipoView({ data, persist }) {
  const [editing, setEditing] = useState(null);
  const [nuevoVehiculo, setNuevoVehiculo] = useState("");
  const [editandoVehiculo, setEditandoVehiculo] = useState(null);
  const blank = { id: "", nombre: "", telefono: "", activo: true };

  const save = (form) => {
    const next = structuredClone(data);
    if (form.id) {
      const i = next.workers.findIndex(w => w.id === form.id);
      next.workers[i] = form;
    } else {
      next.workers.push({ ...form, id: uid("wrk") });
    }
    persist(next);
    setEditing(null);
  };
  const remove = (id) => {
    if (!confirm("¿Eliminar a este trabajador? Se recomienda mejor desactivarlo, para conservar su histórico de horas y rutas.")) return;
    const next = structuredClone(data);
    next.workers = next.workers.filter(w => w.id !== id);
    persist(next);
  };
  const toggleActivo = (id) => {
    const next = structuredClone(data);
    const w = next.workers.find(w => w.id === id);
    w.activo = w.activo === false ? true : false;
    persist(next);
  };

  const vehiculos = data.vehiculos || [];
  const añadirVehiculo = () => {
    if (!nuevoVehiculo.trim()) return;
    const next = structuredClone(data);
    next.vehiculos = [...(next.vehiculos || []), nuevoVehiculo.trim()];
    persist(next);
    setNuevoVehiculo("");
  };
  const guardarVehiculo = (idx, nombre) => {
    const next = structuredClone(data);
    next.vehiculos[idx] = nombre;
    persist(next);
    setEditandoVehiculo(null);
  };
  const eliminarVehiculo = (idx) => {
    const next = structuredClone(data);
    next.vehiculos = next.vehiculos.filter((_, i) => i !== idx);
    persist(next);
  };

  return (
    <div>
      <div className="gj-row" style={{ marginBottom: 10 }}>
        <h2 className="gj-h2" style={{ margin: 0 }}>Equipo</h2>
        <button className="gj-btn primary" onClick={() => setEditing(blank)}><Plus size={14} /> Añadir</button>
      </div>
      <div style={{ fontSize: 12, color: "var(--ink-soft)", marginBottom: 10 }}>
        Si un trabajador deja la empresa, desactívalo en vez de borrarlo: dejará de aparecer para fichar o para asignarle rutas, pero se conserva todo su histórico de horas y vacaciones.
      </div>
      {editing && (
        <div className="gj-card">
          <div className="gj-field"><label className="gj-label">Nombre</label><input className="gj-input" value={editing.nombre} onChange={e => setEditing({ ...editing, nombre: e.target.value })} placeholder="Nombre del trabajador" /></div>
          <div className="gj-field"><label className="gj-label">Teléfono (con prefijo, para WhatsApp)</label><input className="gj-input" value={editing.telefono} onChange={e => setEditing({ ...editing, telefono: e.target.value })} placeholder="34600111222" /></div>
          <div className="gj-row" style={{ gap: 6 }}>
            <button className="gj-btn block" onClick={() => setEditing(null)}>Cancelar</button>
            <button className="gj-btn primary block" onClick={() => editing.nombre.trim() && editing.telefono.trim() && save(editing)}>Guardar</button>
          </div>
        </div>
      )}
      {data.workers.length === 0 && <div className="gj-card gj-empty">Todavía no hay trabajadores.</div>}
      {data.workers.map(w => (
        <div className="gj-card gj-row" key={w.id} style={{ opacity: w.activo === false ? 0.6 : 1 }}>
          <div>
            <div style={{ fontWeight: 600, display: "flex", alignItems: "center", gap: 6 }}>
              {w.nombre}
              {w.activo === false && <span className="gj-badge" style={{ background: "var(--warn-bg)", color: "var(--warn)" }}>Inactivo</span>}
            </div>
            <div style={{ fontSize: 12, color: "var(--ink-soft)" }}>{w.telefono}</div>
          </div>
          <div style={{ display: "flex", gap: 2 }}>
            <button className="gj-btn ghost" onClick={() => toggleActivo(w.id)} title={w.activo === false ? "Reactivar" : "Desactivar (ha dejado la empresa)"}>
              {w.activo === false ? <UserCheck size={14} color="var(--good)" /> : <UserX size={14} color="var(--warn)" />}
            </button>
            <button className="gj-btn ghost" onClick={() => setEditing(w)}><Pencil size={14} /></button>
            <button className="gj-btn ghost" onClick={() => remove(w.id)}><Trash2 size={14} color="var(--warn)" /></button>
          </div>
        </div>
      ))}

      <h3 className="gj-h3" style={{ marginTop: 14 }}>Vehículos</h3>
      <div className="gj-card">
        <div style={{ display: "flex", gap: 6, marginBottom: vehiculos.length > 0 ? 10 : 0 }}>
          <input className="gj-input" value={nuevoVehiculo} onChange={e => setNuevoVehiculo(e.target.value)} placeholder="Nombre del vehículo" />
          <button className="gj-btn primary" onClick={añadirVehiculo}><Plus size={14} /></button>
        </div>
        {vehiculos.map((v, idx) => (
          <div className="gj-row" key={idx} style={{ padding: "5px 0", borderBottom: idx < vehiculos.length - 1 ? "1px solid var(--line-soft)" : "none" }}>
            {editandoVehiculo === idx ? (
              <input className="gj-input" defaultValue={v} autoFocus
                onKeyDown={e => e.key === "Enter" && guardarVehiculo(idx, e.target.value)}
                onBlur={e => guardarVehiculo(idx, e.target.value)} />
            ) : (
              <span style={{ fontSize: 13.5 }}>{v}</span>
            )}
            <div style={{ display: "flex", gap: 2 }}>
              <button className="gj-btn ghost" onClick={() => setEditandoVehiculo(idx)}><Pencil size={13} /></button>
              <button className="gj-btn ghost" onClick={() => eliminarVehiculo(idx)}><Trash2 size={13} color="var(--warn)" /></button>
            </div>
          </div>
        ))}
        {vehiculos.length === 0 && <div style={{ fontSize: 12.5, color: "var(--ink-soft)" }}>Todavía no hay vehículos dados de alta.</div>}
      </div>
    </div>
  );
}

function RutasView({ data, persist, getClient, getWorker, adminMode, requestUnlock }) {
  const [fecha, setFecha] = useState(todayStr());
  const [selWorkers, setSelWorkers] = useState([]);
  const [selClients, setSelClients] = useState([]);
  const [obsDraft, setObsDraft] = useState({});
  const [editingObs, setEditingObs] = useState(null);
  const [editingCrew, setEditingCrew] = useState(null);
  const [selVehiculo, setSelVehiculo] = useState("");

  const toggleCrewMember = (orderId, workerId) => {
    const next = structuredClone(data);
    const order = next.orders.find(o => o.id === orderId);
    if (order.workerIds.includes(workerId)) {
      if (order.workerIds.length <= 1) return;
      order.workerIds = order.workerIds.filter(id => id !== workerId);
    } else {
      order.workerIds = [...order.workerIds, workerId];
    }
    persist(next);
  };

  const toggleWorker = (id) => {
    setSelWorkers(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  };
  const toggleClient = (id) => {
    setSelClients(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  };

  const crear = () => {
    if (selWorkers.length === 0 || selClients.length === 0) return;
    const next = structuredClone(data);
    next.orders.push({
      id: uid("ord"), fecha, workerIds: selWorkers, jornadaFinalizada: false, vehiculo: selVehiculo,
      tiempoCargaMin: 0, tiempoAlmuerzoMin: data.settings.almuerzoEstandarMin || 15,
      stops: selClients.map(cid => ({
        clienteId: cid, estado: "pendiente", resultado: null, horaInicio: null, horaFin: null,
        notificado: false, observaciones: obsDraft[cid] || "", notaTrabajador: "", materiales: "", labores: [],
      })),
    });
    persist(next);
    setSelWorkers([]); setSelClients([]); setObsDraft({}); setSelVehiculo("");
  };

  const eliminar = (id) => {
    if (!confirm("¿Eliminar esta ruta?")) return;
    const next = structuredClone(data);
    next.orders = next.orders.filter(o => o.id !== id);
    persist(next);
  };

  const cambiarVehiculo = (orderId, vehiculo) => {
    const next = structuredClone(data);
    const order = next.orders.find(o => o.id === orderId);
    order.vehiculo = vehiculo;
    persist(next);
  };

  const guardarObs = (orderId, clienteId, texto) => {
    const next = structuredClone(data);
    const order = next.orders.find(o => o.id === orderId);
    order.stops.find(s => s.clienteId === clienteId).observaciones = texto;
    persist(next);
    setEditingObs(null);
  };

  const rutasDelDia = data.orders.filter(o => o.fecha === fecha);

  return (
    <div>
      <h2 className="gj-h2">Rutas</h2>

      {adminMode ? (
        <div className="gj-card">
          <div className="gj-h3">Crear ruta</div>
          <div className="gj-field"><label className="gj-label">Fecha</label><input className="gj-input" type="date" value={fecha} onChange={e => setFecha(e.target.value)} /></div>
          <div className="gj-field">
            <label className="gj-label">Cuadrilla</label>
            <div className="gj-checklist">
              {data.workers.filter(w => w.activo !== false).map(w => (
                <span key={w.id} className={"gj-chip" + (selWorkers.includes(w.id) ? " selected" : "")} onClick={() => toggleWorker(w.id)}>{w.nombre}</span>
              ))}
              {data.workers.filter(w => w.activo !== false).length === 0 && <span style={{ fontSize: 12.5, color: "var(--ink-soft)" }}>Añade trabajadores activos en la pestaña Equipo.</span>}
            </div>
          </div>
          <div className="gj-field">
            <label className="gj-label">Vehículo (opcional)</label>
            <select className="gj-select" value={selVehiculo} onChange={e => setSelVehiculo(e.target.value)}>
              <option value="">Sin asignar</option>
              {(data.vehiculos || []).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="gj-field">
            <label className="gj-label">Clientes de la ruta, en orden</label>
            <div className="gj-checklist">
              {data.clients.map(c => (
                <span key={c.id} className={"gj-chip" + (selClients.includes(c.id) ? " selected" : "")} onClick={() => toggleClient(c.id)}>
                  {selClients.includes(c.id) ? (selClients.indexOf(c.id) + 1) + ". " : ""}{c.nombre}{c.tipo === "obra" ? " (obra)" : ""}
                </span>
              ))}
            </div>
          </div>
          {selClients.length > 0 && (
            <div className="gj-field">
              <label className="gj-label">Observaciones / trabajo extra por cliente (opcional)</label>
              {selClients.map(cid => (
                <input key={cid} className="gj-input" style={{ marginBottom: 6 }}
                  placeholder={`Nota para ${getClient(cid)?.nombre}...`}
                  value={obsDraft[cid] || ""}
                  onChange={e => setObsDraft(prev => ({ ...prev, [cid]: e.target.value }))} />
              ))}
            </div>
          )}
          <button className="gj-btn accent block" disabled={selWorkers.length === 0 || selClients.length === 0} onClick={crear}>
            <Plus size={14} /> Crear ruta
          </button>
        </div>
      ) : (
        <div className="gj-card gj-row" style={{ background: "var(--pend-bg)" }}>
          <div style={{ fontSize: 12.5, color: "var(--ink-soft)" }}>Solo un administrador puede crear o modificar rutas.</div>
          <button className="gj-btn ghost" onClick={requestUnlock}><Lock size={13} /></button>
        </div>
      )}

      <h3 className="gj-h3">Rutas de {fecha}</h3>
      <div className="gj-field" style={{ maxWidth: 180 }}>
        <input className="gj-input" type="date" value={fecha} onChange={e => setFecha(e.target.value)} />
      </div>
      {rutasDelDia.length === 0 && <div className="gj-card gj-empty">No hay rutas creadas para este día.</div>}
      {rutasDelDia.map(o => {
        const crewNames = o.workerIds.map(id => getWorker(id)?.nombre).filter(Boolean).join(", ");
        const listado = o.stops.map((s, i) => `${i + 1}. ${getClient(s.clienteId)?.nombre} — ${getClient(s.clienteId)?.direccion}${s.observaciones ? " (obs: " + s.observaciones + ")" : ""}`).join("\n");
        return (
          <div className="gj-card" key={o.id}>
            <div className="gj-row">
              <div style={{ fontWeight: 600 }}>{crewNames}</div>
              {adminMode && <button className="gj-btn ghost" onClick={() => eliminar(o.id)}><Trash2 size={14} color="var(--warn)" /></button>}
            </div>
            <div style={{ fontSize: 12, color: "var(--ink-soft)", marginBottom: 4, display: "flex", alignItems: "center", gap: 6 }}>
              Vehículo:
              {adminMode ? (
                <select className="gj-select" style={{ width: "auto", padding: "3px 6px", fontSize: 12 }} value={o.vehiculo || ""} onChange={e => cambiarVehiculo(o.id, e.target.value)}>
                  <option value="">Sin asignar</option>
                  {(data.vehiculos || []).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              ) : (o.vehiculo || "sin asignar")}
            </div>
            {adminMode && (
              editingCrew === o.id ? (
                <div style={{ margin: "6px 0" }}>
                  <div className="gj-checklist">
                    {data.workers.filter(w => w.activo !== false || o.workerIds.includes(w.id)).map(w => (
                      <span key={w.id} className={"gj-chip" + (o.workerIds.includes(w.id) ? " selected" : "")} onClick={() => toggleCrewMember(o.id, w.id)}>{w.nombre}{w.activo === false ? " (inactivo)" : ""}</span>
                    ))}
                  </div>
                  <div style={{ fontSize: 11, color: "var(--ink-soft)", marginTop: 4 }}>Toca para añadir o quitar a alguien de esta ruta. Debe quedar al menos 1 persona.</div>
                  <button className="gj-btn ghost" style={{ padding: "3px 4px", fontSize: 11.5, marginTop: 2 }} onClick={() => setEditingCrew(null)}>Listo</button>
                </div>
              ) : (
                <button className="gj-btn ghost" style={{ padding: "3px 4px", fontSize: 11.5, marginBottom: 4 }} onClick={() => setEditingCrew(o.id)}>
                  <Pencil size={11} /> Editar cuadrilla
                </button>
              )
            )}
            {o.stops.map((s, i) => {
              const cli = getClient(s.clienteId);
              return (
                <div key={s.clienteId} style={{ padding: "6px 0", borderBottom: "1px solid var(--line-soft)" }}>
                  <div className="gj-row">
                    <span style={{ fontSize: 13 }}>{i + 1}. {cli?.nombre}</span>
                    <span className={"gj-badge " + (s.resultado === "no_hecho" ? "no_hecho" : s.estado)}>
                      {s.resultado === "no_hecho" ? "no hecho" : s.estado.replace("_", " ")}
                    </span>
                  </div>
                  {s.observaciones && !editingObs && (
                    <div style={{ fontSize: 12, color: "var(--ink-soft)", marginTop: 2 }}>Obs: {s.observaciones}</div>
                  )}
                  {adminMode && editingObs === o.id + s.clienteId ? (
                    <div style={{ display: "flex", gap: 6, marginTop: 4 }}>
                      <input className="gj-input" defaultValue={s.observaciones}
                        onKeyDown={e => e.key === "Enter" && guardarObs(o.id, s.clienteId, e.target.value)}
                        id={"obs-" + o.id + s.clienteId} />
                      <button className="gj-btn" onClick={() => guardarObs(o.id, s.clienteId, document.getElementById("obs-" + o.id + s.clienteId).value)}>Guardar</button>
                    </div>
                  ) : adminMode ? (
                    <button className="gj-btn ghost" style={{ padding: "3px 4px", fontSize: 11.5 }} onClick={() => setEditingObs(o.id + s.clienteId)}>
                      <Pencil size={11} /> {s.observaciones ? "Editar observación" : "Añadir observación"}
                    </button>
                  ) : null}
                </div>
              );
            })}
            {adminMode && (
              <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 8 }}>
                {o.workerIds.map(wid => {
                  const w = getWorker(wid);
                  const companeros = o.workerIds.filter(id => id !== wid).map(id => getWorker(id)?.nombre).filter(Boolean);
                  const lineaCompaneros = companeros.length > 0 ? `Vas con: ${companeros.join(", ")}` : "Vas solo/a en esta ruta.";
                  const lineaVehiculo = `Vehículo: ${o.vehiculo || "sin asignar"}`;
                  const mensajePersonal = `Hola ${w?.nombre}, para hoy ${fechaEs(o.fecha)} tenéis asignada esta ruta:\n${listado}\n\n${lineaVehiculo}\n${lineaCompaneros}\n\nMarcad inicio y fin de cada mantenimiento desde la app. ¡Buen trabajo!`;
                  return (
                    <a key={wid} className="gj-btn accent" href={waLink(w?.telefono, mensajePersonal)} target="_blank" rel="noreferrer">
                      <Send size={13} /> Enviar a {w?.nombre}
                    </a>
                  );
                })}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function TrabajadorView({ data, persist, getClient, getWorker, deviceWorkerId, reasignarDispositivo, adminMode, requestUnlock }) {
  const workerId = (deviceWorkerId && deviceWorkerId !== "__admin__") ? deviceWorkerId : "";
  const worker = workerId ? getWorker(workerId) : null;
  const [notaAbierta, setNotaAbierta] = useState(null);
  const [laboresAbiertas, setLaboresAbiertas] = useState(null);
  const [notaTexto, setNotaTexto] = useState("");
  const today = todayStr();
  const misOrdenes = data.orders.filter(o => o.fecha === today && o.workerIds.includes(workerId));

  const updateStop = (orderId, clienteId, patch) => {
    const next = structuredClone(data);
    const order = next.orders.find(o => o.id === orderId);
    const stop = order.stops.find(s => s.clienteId === clienteId);
    Object.assign(stop, patch);
    persist(next);
  };

  const toggleLabor = (orderId, clienteId, labor) => {
    const next = structuredClone(data);
    const order = next.orders.find(o => o.id === orderId);
    const stop = order.stops.find(s => s.clienteId === clienteId);
    stop.labores = stop.labores || [];
    if (stop.labores.includes(labor)) stop.labores = stop.labores.filter(l => l !== labor);
    else stop.labores = [...stop.labores, labor];
    persist(next);
  };

  const marcarNoHecho = (orderId, clienteId) => {
    const next = structuredClone(data);
    const order = next.orders.find(o => o.id === orderId);
    const stop = order.stops.find(s => s.clienteId === clienteId);
    stop.estado = "completado"; stop.resultado = "no_hecho"; stop.horaFin = nowTime(); stop.notaTrabajador = notaTexto; stop.crewSize = order.workerIds.length;
    next.pendientes = next.pendientes || [];
    next.pendientes.push({
      id: uid("pnd"), clienteId, descripcion: notaTexto || "No se pudo completar el mantenimiento",
      origen: "trabajador", autor: getWorker(workerId)?.nombre || "Trabajador", fecha: today, resuelto: false,
    });
    persist(next);
    setNotaAbierta(null); setNotaTexto("");
  };

  const finalizarJornada = (orderId) => {
    const next = structuredClone(data);
    const order = next.orders.find(o => o.id === orderId);
    order.jornadaFinalizada = true;
    persist(next);
  };

  const updateTiempoOrden = (orderId, campo, valor) => {
    const next = structuredClone(data);
    const order = next.orders.find(o => o.id === orderId);
    order[campo] = Math.max(0, Number(valor) || 0);
    persist(next);
  };

  const empezarAlmuerzo = async (orderId) => {
    const coord = await getPosicionActual();
    const next = structuredClone(data);
    const order = next.orders.find(o => o.id === orderId);
    order.almuerzoInicio = nowTime();
    order.almuerzoInicioCoord = coord;
    order.almuerzoFin = null;
    order.almuerzoFinCoord = null;
    order.avisoTiempoAlmuerzo = false;
    order.avisoUbicacionAlmuerzo = false;
    persist(next);
  };

  const terminarAlmuerzo = async (orderId) => {
    const coord = await getPosicionActual();
    const next = structuredClone(data);
    const order = next.orders.find(o => o.id === orderId);
    order.almuerzoFin = nowTime();
    order.almuerzoFinCoord = coord;

    const minutosReales = diffHours(order.almuerzoInicio, order.almuerzoFin) * 60;
    const limite = (order.tiempoAlmuerzoMin || data.settings.almuerzoEstandarMin || 15) + 20;
    order.avisoTiempoAlmuerzo = minutosReales > limite;

    order.avisoUbicacionAlmuerzo = false;
    const clientesRuta = order.stops.map(s => getClient(s.clienteId)).filter(c => c && c.lat && c.lng);
    if (clientesRuta.length > 0) {
      const coordsAComprobar = [order.almuerzoInicioCoord, order.almuerzoFinCoord].filter(Boolean);
      const fueraDeRango = coordsAComprobar.some(pos => {
        const distMin = Math.min(...clientesRuta.map(c => distanciaKm(pos.lat, pos.lng, c.lat, c.lng)));
        return distMin > 0.05;
      });
      order.avisoUbicacionAlmuerzo = fueraDeRango || coordsAComprobar.length === 0;
    }
    persist(next);
  };

  return (
    <div>
      <h2 className="gj-h2">Fichar</h2>

      {deviceWorkerId === "__admin__" ? (
        <div className="gj-card gj-empty">
          Este dispositivo está configurado como "solo administración" y no puede fichar.
          {adminMode && <div style={{ marginTop: 10 }}><button className="gj-btn primary" onClick={reasignarDispositivo}>Asignar un trabajador a este dispositivo</button></div>}
        </div>
      ) : !worker ? (
        <div className="gj-card gj-empty">
          El trabajador asignado a este dispositivo ya no está activo o no existe.
          {adminMode ? (
            <div style={{ marginTop: 10 }}><button className="gj-btn primary" onClick={reasignarDispositivo}>Reasignar este dispositivo</button></div>
          ) : (
            <div style={{ marginTop: 6, fontSize: 12 }}>Pide a un administrador que reasigne este dispositivo.</div>
          )}
        </div>
      ) : (
        <>
      <div className="gj-card gj-row">
        <div>
          <div className="gj-label" style={{ marginBottom: 2 }}>Fichando como</div>
          <div style={{ fontWeight: 600 }}>{worker.nombre}</div>
        </div>
        {adminMode && <button className="gj-btn ghost" onClick={reasignarDispositivo} title="Reasignar este dispositivo a otro trabajador">Cambiar</button>}
      </div>

      {misOrdenes.length === 0 && <div className="gj-card gj-empty">No tienes ninguna ruta asignada hoy.</div>}

      {misOrdenes.map(o => {
        const todosCompletados = o.stops.every(s => s.estado === "completado");
        return (
          <div className="gj-card" key={o.id}>
            <div className="gj-h3" style={{ marginBottom: 10 }}>Tu ruta de hoy</div>
            <div className="gj-grid2" style={{ marginBottom: 10 }}>
              <div className="gj-field" style={{ marginBottom: 0 }}>
                <label className="gj-label">Tiempo de carga (min)</label>
                <input className="gj-input" type="number" value={o.tiempoCargaMin || 0} onChange={e => updateTiempoOrden(o.id, "tiempoCargaMin", e.target.value)} />
              </div>
              <div className="gj-field" style={{ marginBottom: 0 }}>
                <label className="gj-label">Tiempo de almuerzo (min)</label>
                <input className="gj-input" type="number" value={o.tiempoAlmuerzoMin ?? (data.settings.almuerzoEstandarMin || 15)} onChange={e => updateTiempoOrden(o.id, "tiempoAlmuerzoMin", e.target.value)} />
              </div>
            </div>
            <div style={{ marginBottom: 10, padding: 8, background: "var(--pend-bg)", borderRadius: 4 }}>
              <div style={{ fontSize: 11, fontWeight: 600, color: "var(--ink-soft)", marginBottom: 6 }}>Almuerzo</div>
              {!o.almuerzoInicio ? (
                <button className="gj-btn accent block" onClick={() => empezarAlmuerzo(o.id)}>Empezar almuerzo</button>
              ) : !o.almuerzoFin ? (
                <button className="gj-btn primary block" onClick={() => terminarAlmuerzo(o.id)}>Terminar almuerzo</button>
              ) : (
                <div>
                  <div style={{ fontSize: 12.5 }}>{o.almuerzoInicio} – {o.almuerzoFin}</div>
                  {adminMode && (
                    <div style={{ display: "flex", gap: 10, marginTop: 2 }}>
                      {o.almuerzoInicioCoord ? (
                        <a href={mapsLinkCoord(o.almuerzoInicioCoord)} target="_blank" rel="noreferrer" style={{ fontSize: 11.5 }}>📍 Ver inicio</a>
                      ) : <span style={{ fontSize: 11.5, color: "var(--warn)" }}>Sin ubicación de inicio</span>}
                      {o.almuerzoFinCoord ? (
                        <a href={mapsLinkCoord(o.almuerzoFinCoord)} target="_blank" rel="noreferrer" style={{ fontSize: 11.5 }}>📍 Ver fin</a>
                      ) : <span style={{ fontSize: 11.5, color: "var(--warn)" }}>Sin ubicación de fin</span>}
                    </div>
                  )}
                  <div style={{ display: "flex", gap: 4, flexWrap: "wrap", marginTop: 4 }}>
                    {o.avisoTiempoAlmuerzo && <span className="gj-badge no_hecho">Tiempo superado (+20 min)</span>}
                    {adminMode && o.avisoUbicacionAlmuerzo && <span className="gj-badge no_hecho">Ubicación no coincide con la ruta</span>}
                    {!o.avisoTiempoAlmuerzo && (!adminMode || !o.avisoUbicacionAlmuerzo) && <span className="gj-badge completado">Todo correcto</span>}
                  </div>
                </div>
              )}
            </div>
            {o.stops.map(s => {
              const cli = getClient(s.clienteId);
              const dur = s.estado === "completado" ? diffHours(s.horaInicio, s.horaFin) : 0;
              const key = o.id + s.clienteId;
              return (
                <div key={s.clienteId} style={{ padding: "8px 0", borderBottom: "1px solid var(--line-soft)" }}>
                  <div className="gj-row">
                    <div>
                      <div style={{ fontWeight: 600, fontSize: 13.5 }}>{cli?.nombre}</div>
                      <div style={{ fontSize: 11.5, color: "var(--ink-soft)", display: "flex", alignItems: "center", gap: 4 }}>
                        {cli?.direccion}
                        <a href={mapsLink(cli?.direccion)} target="_blank" rel="noreferrer" title="Cómo llegar">
                          <MapPin size={12} color="var(--accent)" />
                        </a>
                      </div>
                    </div>
                    <span className={"gj-badge " + (s.resultado === "no_hecho" ? "no_hecho" : s.estado)}>
                      {s.resultado === "no_hecho" ? "no hecho" : s.estado.replace("_", " ")}
                    </span>
                  </div>
                  {s.observaciones !== undefined && (
                    <div style={{ marginTop: 6 }}>
                      <label className="gj-label" style={{ marginBottom: 2 }}>Observaciones</label>
                      <input className="gj-input" defaultValue={s.observaciones || ""} placeholder="Escribe aquí cualquier observación de esta visita"
                        onBlur={e => updateStop(o.id, s.clienteId, { observaciones: e.target.value })} />
                    </div>
                  )}
                  {(data.pendientes || []).filter(p => p.clienteId === s.clienteId && !p.resuelto).length > 0 && (
                    <div style={{ marginTop: 4, padding: 6, background: "var(--pend-bg)", borderRadius: 3 }}>
                      <div style={{ fontSize: 11, fontWeight: 600, color: "var(--ink-soft)", marginBottom: 2 }}>Pendientes de este cliente:</div>
                      {(data.pendientes || []).filter(p => p.clienteId === s.clienteId && !p.resuelto).map(p => (
                        <div key={p.id} style={{ fontSize: 12 }}>
                          • {p.descripcion} <span style={{ color: "var(--ink-soft)", fontSize: 11 }}>({p.origen === "cliente" ? "cliente" : "trabajador"})</span>
                        </div>
                      ))}
                    </div>
                  )}
                  {cli?.tipo !== "obra" && (
                    <div style={{ marginTop: 6 }}>
                      <button className="gj-btn ghost" style={{ padding: "4px 6px", fontSize: 11.5 }}
                        onClick={() => setLaboresAbiertas(laboresAbiertas === key ? null : key)}>
                        <ListChecks size={12} /> Labores realizadas {(s.labores && s.labores.length > 0) ? `(${s.labores.length})` : ""}
                      </button>
                      {laboresAbiertas === key && (
                        <div style={{ marginTop: 4, padding: 8, background: "var(--pend-bg)", borderRadius: 4 }}>
                          {LABORES_ESTANDAR.map(labor => (
                            <label key={labor} className="gj-row" style={{ cursor: "pointer", padding: "3px 0" }}>
                              <span style={{ fontSize: 12.5 }}>{labor}</span>
                              <input type="checkbox" checked={(s.labores || []).includes(labor)} onChange={() => toggleLabor(o.id, s.clienteId, labor)} />
                            </label>
                          ))}
                        </div>
                      )}
                    {!laboresAbiertas && s.labores && s.labores.length > 0 && (
                      <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginTop: 2 }}>{s.labores.join(", ")}</div>
                    )}
                  </div>
                  )}
                  <div style={{ marginTop: 6 }}>
                    <label className="gj-label" style={{ marginBottom: 2 }}>Materiales aportados/utilizados (opcional)</label>
                    <input className="gj-input" defaultValue={s.materiales || ""} placeholder="Ej: 2 sacos de sustrato, manguera 10m"
                      onBlur={e => updateStop(o.id, s.clienteId, { materiales: e.target.value })} />
                  </div>
                  <div className="gj-row" style={{ marginTop: 6 }}>
                    <div style={{ fontSize: 12, color: "var(--ink-soft)" }}>
                      {s.horaInicio ? `Inicio ${s.horaInicio}` : ""}{s.horaFin ? ` · Fin ${s.horaFin} · ${fmtHM(dur)}` : ""}
                    </div>
                    {s.estado === "pendiente" && (
                      <button className="gj-btn accent" onClick={() => updateStop(o.id, s.clienteId, { estado: "en_progreso", horaInicio: nowTime() })}>
                        <Play size={13} /> Iniciar
                      </button>
                    )}
                    {s.estado === "en_progreso" && notaAbierta !== key && (
                      <div style={{ display: "flex", gap: 6 }}>
                        <button className="gj-btn primary" onClick={() => updateStop(o.id, s.clienteId, { estado: "completado", resultado: "hecho", horaFin: nowTime(), crewSize: o.workerIds.length })}>
                          <CheckCircle2 size={13} /> Hecho
                        </button>
                        <button className="gj-btn danger" onClick={() => { setNotaAbierta(key); setNotaTexto(""); }}>
                          <XCircle size={13} /> No hecho
                        </button>
                      </div>
                    )}
                    {s.estado === "completado" && s.resultado !== "no_hecho" && <CheckCircle2 size={16} color="var(--good)" />}
                    {s.resultado === "no_hecho" && <AlertTriangle size={16} color="var(--warn)" />}
                  </div>
                  {notaAbierta === key && (
                    <div style={{ marginTop: 6 }}>
                      <textarea className="gj-input" rows={2} placeholder="¿Qué ha pasado o qué falta?"
                        value={notaTexto} onChange={e => setNotaTexto(e.target.value)} />
                      <div className="gj-row" style={{ marginTop: 4, gap: 6 }}>
                        <button className="gj-btn block" onClick={() => setNotaAbierta(null)}>Cancelar</button>
                        <button className="gj-btn danger block" onClick={() => marcarNoHecho(o.id, s.clienteId)}>Confirmar no hecho</button>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
            {o.jornadaFinalizada ? (
              <div style={{ marginTop: 10, fontSize: 12.5, color: "var(--good)", fontWeight: 600 }}>Jornada finalizada ✓</div>
            ) : (
              <button className="gj-btn primary block" style={{ marginTop: 10 }} disabled={!todosCompletados} onClick={() => finalizarJornada(o.id)}>
                Finalizar jornada
              </button>
            )}
          </div>
        );
      })}
        </>
      )}
    </div>
  );
}

function PendientesView({ data, persist, getClient, adminMode }) {
  const [clienteId, setClienteId] = useState("");
  const [descripcion, setDescripcion] = useState("");
  const [origen, setOrigen] = useState("trabajador");
  const [autor, setAutor] = useState("");

  const añadir = () => {
    if (!descripcion.trim()) return;
    const next = structuredClone(data);
    next.pendientes = next.pendientes || [];
    next.pendientes.push({
      id: uid("pnd"), clienteId: clienteId || null, descripcion, origen,
      autor: autor.trim() || (origen === "cliente" ? "Cliente" : "Trabajador"), fecha: todayStr(), resuelto: false,
    });
    persist(next);
    setDescripcion(""); setAutor("");
  };

  const toggleResuelto = (id) => {
    const next = structuredClone(data);
    const p = next.pendientes.find(x => x.id === id);
    p.resuelto = !p.resuelto;
    persist(next);
  };

  const eliminar = (id) => {
    const next = structuredClone(data);
    next.pendientes = next.pendientes.filter(x => x.id !== id);
    persist(next);
  };

  const pendientes = (data.pendientes || []).slice().sort((a, b) => (a.resuelto === b.resuelto ? 0 : a.resuelto ? 1 : -1));

  return (
    <div>
      <h2 className="gj-h2">Trabajos pendientes</h2>
      <div className="gj-card">
        <div className="gj-h3">Añadir</div>
        <div className="gj-field">
          <label className="gj-label">Cliente (opcional)</label>
          <select className="gj-select" value={clienteId} onChange={e => setClienteId(e.target.value)}>
            <option value="">General / sin cliente concreto</option>
            {data.clients.map(c => <option key={c.id} value={c.id}>{c.nombre}{c.tipo === "obra" ? " (obra)" : ""}</option>)}
          </select>
        </div>
        <div className="gj-field"><label className="gj-label">¿Qué hay que hacer?</label>
          <textarea className="gj-input" rows={2} value={descripcion} onChange={e => setDescripcion(e.target.value)} placeholder="Ej: podar el seto de la entrada, el cliente lo pidió por teléfono" />
        </div>
        <div className="gj-grid2">
          <div className="gj-field"><label className="gj-label">Origen</label>
            <select className="gj-select" value={origen} onChange={e => setOrigen(e.target.value)}>
              <option value="trabajador">Visto por un trabajador</option>
              <option value="cliente">Solicitado por el cliente</option>
            </select>
          </div>
          <div className="gj-field"><label className="gj-label">Nombre (opcional)</label>
            <input className="gj-input" value={autor} onChange={e => setAutor(e.target.value)} placeholder="Quién lo apunta" />
          </div>
        </div>
        <button className="gj-btn accent block" onClick={añadir}><Plus size={14} /> Añadir a pendientes</button>
      </div>

      {pendientes.length === 0 && <div className="gj-card gj-empty">No hay trabajos pendientes anotados.</div>}
      {pendientes.map(p => {
        const cli = p.clienteId ? getClient(p.clienteId) : null;
        return (
          <div className="gj-card" key={p.id} style={{ opacity: p.resuelto ? 0.55 : 1 }}>
            <div className="gj-row">
              <span className="gj-badge" style={{ background: p.origen === "cliente" ? "var(--good-bg)" : "var(--pend-bg)", color: p.origen === "cliente" ? "var(--good)" : "var(--ink-soft)" }}>
                {p.origen === "cliente" ? "cliente" : "trabajador"}
              </span>
              {adminMode && <button className="gj-btn ghost" onClick={() => eliminar(p.id)}><Trash2 size={13} color="var(--warn)" /></button>}
            </div>
            <div style={{ fontWeight: 600, fontSize: 13.5, marginTop: 4 }}>{cli ? cli.nombre : "General"}</div>
            <div style={{ fontSize: 13, marginTop: 2 }}>{p.descripcion}</div>
            <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginTop: 4 }}>{p.autor} · {p.fecha}</div>
            <button className="gj-btn" style={{ marginTop: 8 }} onClick={() => toggleResuelto(p.id)}>
              {p.resuelto ? "Marcar como pendiente" : "Marcar como resuelto"}
            </button>
          </div>
        );
      })}
    </div>
  );
}

function HorasView({ data, persist, getWorker, adminMode }) {
  const now = new Date();
  const [workerId, setWorkerId] = useState(data.workers[0]?.id || "");
  const [year, setYear] = useState(now.getFullYear());
  const [month, setMonth] = useState(now.getMonth());
  const [tipoMarca, setTipoMarca] = useState("vacaciones");

  const horasPorDia = {};
  data.orders.forEach(o => {
    if (!o.workerIds.includes(workerId)) return;
    let algunaCompletada = false;
    o.stops.forEach(s => {
      if (s.estado === "completado") {
        algunaCompletada = true;
        horasPorDia[o.fecha] = (horasPorDia[o.fecha] || 0) + diffHours(s.horaInicio, s.horaFin);
      }
    });
    if (algunaCompletada) {
      horasPorDia[o.fecha] = (horasPorDia[o.fecha] || 0) + minutosExtraOrden(o) / 60;
    }
  });

  const vacacionesTrabajador = data.vacaciones[workerId] || {};

  const diasTrabajadosAnio = Object.keys(horasPorDia).filter(d => d.startsWith(String(year))).length;
  const horasAnio = Object.entries(horasPorDia).filter(([d]) => d.startsWith(String(year))).reduce((a, [, h]) => a + h, 0);
  const entradasAnio = Object.entries(vacacionesTrabajador).filter(([d]) => d.startsWith(String(year)));
  const vacacionesAnio = entradasAnio.filter(([, tipo]) => tipo === "vacaciones").length;
  const bajaAnio = entradasAnio.filter(([, tipo]) => tipo === "baja").length;
  const permisoAnio = entradasAnio.filter(([, tipo]) => tipo === "permiso").length;

  const toggleVacacion = (dateStr) => {
    if (!adminMode) return;
    const next = structuredClone(data);
    next.vacaciones[workerId] = next.vacaciones[workerId] || {};
    if (next.vacaciones[workerId][dateStr] === tipoMarca) delete next.vacaciones[workerId][dateStr];
    else next.vacaciones[workerId][dateStr] = tipoMarca;
    persist(next);
  };

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const todayKey = todayStr();
  const prevMonth = () => { if (month === 0) { setMonth(11); setYear(y => y - 1); } else setMonth(m => m - 1); };
  const nextMonth = () => { if (month === 11) { setMonth(0); setYear(y => y + 1); } else setMonth(m => m + 1); };

  const claseDelDia = (y, m, d, horas, tipoAusencia) => {
    if (tipoAusencia === "vacaciones") return "vacation";
    if (tipoAusencia === "baja") return "baja";
    if (tipoAusencia === "permiso") return "permiso";
    if (!horas) return "";
    const dow = new Date(y, m, d).getDay();
    if (dow === 6) return "over";
    const totalMin = Math.round(horas * 60);
    if (totalMin < 480) return "short";
    if (totalMin <= 490) return "";
    return "long";
  };

  return (
    <div>
      <h2 className="gj-h2">Horas, vacaciones, bajas y permisos</h2>
      <div className="gj-card">
        <label className="gj-label">Trabajador</label>
        <select className="gj-select" value={workerId} onChange={e => setWorkerId(e.target.value)}>
          {data.workers.map(w => <option key={w.id} value={w.id}>{w.nombre}{w.activo === false ? " (inactivo)" : ""}</option>)}
        </select>
      </div>

      <div className="gj-grid2" style={{ marginBottom: 12 }}>
        <div className="gj-stat"><div className="n">{fmtHM(horasAnio)}</div><div className="l">Horas trabajadas en {year}</div></div>
        <div className="gj-stat"><div className="n">{diasTrabajadosAnio}</div><div className="l">Días trabajados en {year}</div></div>
        <div className="gj-stat"><div className="n">{vacacionesAnio} / {data.settings.vacacionesAnuales}</div><div className="l">Días de vacaciones tomados</div></div>
        <div className="gj-stat"><div className="n">{bajaAnio}</div><div className="l">Días de baja o enfermedad</div></div>
        <div className="gj-stat"><div className="n">{permisoAnio}</div><div className="l">Días de permiso retribuido</div></div>
      </div>

      {adminMode && (
        <div className="gj-field">
          <label className="gj-label">Tipo de marca a aplicar al tocar un día</label>
          <select className="gj-select" value={tipoMarca} onChange={e => setTipoMarca(e.target.value)}>
            <option value="vacaciones">Vacaciones</option>
            <option value="baja">Baja o enfermedad</option>
            <option value="permiso">Permiso retribuido</option>
          </select>
        </div>
      )}

      <div className="gj-row" style={{ marginBottom: 6 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <button className="gj-btn ghost" onClick={prevMonth}><ChevronLeft size={16} /></button>
          <span style={{ fontSize: 13, fontWeight: 600, minWidth: 90, textAlign: "center" }}>{MESES[month]} {year}</span>
          <button className="gj-btn ghost" onClick={nextMonth}><ChevronRight size={16} /></button>
        </div>
        <div style={{ fontSize: 11, color: "var(--ink-soft)", display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
          <span style={{ display: "flex", alignItems: "center", gap: 3 }}><span style={{ width: 10, height: 10, borderRadius: "50%", border: "1px solid var(--line)", background: "#fff", display: "inline-block" }} /> jornada normal (hasta 8h10)</span>
          <span style={{ display: "flex", alignItems: "center", gap: 3 }}><span style={{ width: 10, height: 10, borderRadius: "50%", background: "var(--good)", display: "inline-block" }} /> vacaciones</span>
          <span style={{ display: "flex", alignItems: "center", gap: 3 }}><span style={{ width: 10, height: 10, borderRadius: "50%", background: "var(--sick)", display: "inline-block" }} /> baja / enfermedad</span>
          <span style={{ display: "flex", alignItems: "center", gap: 3 }}><span style={{ width: 10, height: 10, borderRadius: "50%", background: "var(--permit)", display: "inline-block" }} /> permiso retribuido</span>
          <span style={{ display: "flex", alignItems: "center", gap: 3 }}><span style={{ width: 10, height: 10, borderRadius: "50%", background: "var(--accent)", display: "inline-block" }} /> más de 8h10 (L-V)</span>
          <span style={{ display: "flex", alignItems: "center", gap: 3 }}><span style={{ width: 10, height: 10, borderRadius: "50%", background: "var(--warn)", display: "inline-block" }} /> &lt;8h (L-V)</span>
          <span style={{ display: "flex", alignItems: "center", gap: 3 }}><span style={{ width: 10, height: 10, borderRadius: "50%", background: "var(--highlight)", display: "inline-block" }} /> sábado trabajado</span>
        </div>
      </div>
      <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginBottom: 8 }}>
        {adminMode ? "Toca un día para marcarlo o quitarlo con el tipo seleccionado arriba." : "Solo un administrador puede marcar vacaciones, bajas o permisos."}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 4, maxWidth: 320 }}>
        {days.map(d => {
          const dateStr = `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
          const horas = horasPorDia[dateStr];
          const tipoAusencia = vacacionesTrabajador[dateStr] || null;
          const cls = claseDelDia(year, month, d, horas, tipoAusencia);
          const etiquetas = { vacaciones: "Vacaciones", baja: "Baja o enfermedad", permiso: "Permiso retribuido" };
          return (
            <div key={d}
              className={"gj-daycell" + (cls ? " " + cls : "") + (dateStr === todayKey ? " today" : "")}
              style={{ width: "100%", height: 30, borderRadius: 4, cursor: adminMode ? "pointer" : "default" }}
              onClick={() => toggleVacacion(dateStr)}
              title={tipoAusencia ? etiquetas[tipoAusencia] : horas ? fmtHM(horas) + " trabajadas" : ""}>
              {d}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ExportarView({ data, getClient, getWorker }) {
  const [year, setYear] = useState(new Date().getFullYear());
  const [month, setMonth] = useState(new Date().getMonth());
  const [clienteId, setClienteId] = useState(data.clients[0]?.id || "");

  const visitasAnio = [];
  data.orders.forEach(o => {
    if (!o.fecha.startsWith(String(year))) return;
    o.stops.forEach(s => {
      if (s.estado !== "completado") return;
      visitasAnio.push({
        clienteId: s.clienteId,
        cliente: getClient(s.clienteId)?.nombre || "Cliente eliminado",
        fecha: o.fecha,
        horaInicio: s.horaInicio,
        horaFin: s.horaFin,
        horas: diffHours(s.horaInicio, s.horaFin),
        cuadrilla: o.workerIds.map(id => getWorker(id)?.nombre).filter(Boolean).join(", "),
        resultado: s.resultado === "no_hecho" ? "No hecho" : "Hecho",
        observaciones: s.observaciones || "",
        nota: s.notaTrabajador || "",
        materiales: s.materiales || "",
        labores: (s.labores || []).join(", "),
      });
    });
  });
  visitasAnio.sort((a, b) => a.fecha.localeCompare(b.fecha) || a.horaInicio?.localeCompare(b.horaInicio || ""));

  const exportarVisitas = () => {
    downloadCSV(`visitas_${year}.csv`,
      ["Cliente", "Fecha", "Hora inicio", "Hora fin", "Horas", "Cuadrilla", "Resultado", "Observaciones", "Nota trabajador", "Materiales", "Labores"],
      visitasAnio.map(v => [v.cliente, v.fecha, v.horaInicio, v.horaFin, v.horas.toFixed(2), v.cuadrilla, v.resultado, v.observaciones, v.nota, v.materiales, v.labores])
    );
  };

  const exportarRentabilidad = () => {
    const filas = data.clients.filter(c => c.tipo !== "obra").map(c => {
      let horasPersona = 0;
      data.orders.forEach(o => {
        if (!o.fecha.startsWith(String(year))) return;
        o.stops.forEach(s => {
          if (s.clienteId === c.id && s.estado === "completado") {
            horasPersona += diffHours(s.horaInicio, s.horaFin) * (s.crewSize || o.workerIds.length);
          }
        });
      });
      const cuotaAnual = c.cuotaMensual * 12;
      const costeAnual = horasPersona * (Number(data.settings.costeHora) || 0);
      const beneficio = cuotaAnual - costeAnual;
      const margen = cuotaAnual > 0 ? (beneficio / cuotaAnual) * 100 : 0;
      return [c.nombre, horasPersona.toFixed(2), cuotaAnual.toFixed(2), costeAnual.toFixed(2), beneficio.toFixed(2), margen.toFixed(0) + "%"];
    });
    downloadCSV(`rentabilidad_${year}.csv`,
      ["Cliente", "Horas-persona", "Cuota anual (€)", "Coste estimado (€)", "Beneficio (€)", "Margen"],
      filas
    );
  };

  const exportarRentabilidadObras = () => {
    const costeHora = Number(data.settings.costeHora) || 0;
    const filas = data.clients.filter(c => c.tipo === "obra").map(c => {
      let horasPersona = 0;
      data.orders.forEach(o => {
        o.stops.forEach(s => {
          if (s.clienteId === c.id && s.estado === "completado") {
            horasPersona += diffHours(s.horaInicio, s.horaFin) * (s.crewSize || o.workerIds.length);
          }
        });
      });
      const costeEstimado = horasPersona * costeHora;
      const beneficio = c.presupuesto - costeEstimado;
      const margen = c.presupuesto > 0 ? (beneficio / c.presupuesto) * 100 : 0;
      return [c.nombre, c.estadoObra === "finalizada" ? "Finalizada" : "En curso", horasPersona.toFixed(2), c.presupuesto.toFixed(2), costeEstimado.toFixed(2), beneficio.toFixed(2), margen.toFixed(0) + "%"];
    });
    downloadCSV("rentabilidad_obras.csv",
      ["Obra", "Estado", "Horas-persona", "Presupuesto (€)", "Coste estimado (€)", "Beneficio (€)", "Margen"],
      filas
    );
  };

  const horasPorDiaTrabajador = {};
  data.orders.forEach(o => {
    if (!o.fecha.startsWith(String(year))) return;
    let algunaCompletada = false;
    o.stops.forEach(s => {
      if (s.estado !== "completado") return;
      algunaCompletada = true;
      const horas = diffHours(s.horaInicio, s.horaFin);
      o.workerIds.forEach(wid => {
        const key = wid + "|" + o.fecha;
        horasPorDiaTrabajador[key] = (horasPorDiaTrabajador[key] || 0) + horas;
      });
    });
    if (algunaCompletada) {
      const extra = minutosExtraOrden(o) / 60;
      o.workerIds.forEach(wid => {
        const key = wid + "|" + o.fecha;
        horasPorDiaTrabajador[key] = (horasPorDiaTrabajador[key] || 0) + extra;
      });
    }
  });

  const exportarHorasDia = () => {
    const filas = Object.entries(horasPorDiaTrabajador).map(([key, horas]) => {
      const idx = key.lastIndexOf("|");
      return { worker: getWorker(key.slice(0, idx))?.nombre || "Trabajador eliminado", fecha: key.slice(idx + 1), horas };
    }).sort((a, b) => a.fecha.localeCompare(b.fecha) || a.worker.localeCompare(b.worker));
    downloadCSV(`horas_por_dia_${year}.csv`,
      ["Trabajador", "Fecha", "Horas"],
      filas.map(f => [f.worker, f.fecha, f.horas.toFixed(2)])
    );
  };

  const exportarHorasMes = () => {
    const porMes = {};
    Object.entries(horasPorDiaTrabajador).forEach(([key, horas]) => {
      const idx = key.lastIndexOf("|");
      const wid = key.slice(0, idx);
      const mes = key.slice(idx + 1).slice(0, 7);
      const mkey = wid + "|" + mes;
      porMes[mkey] = (porMes[mkey] || 0) + horas;
    });
    const filas = Object.entries(porMes).map(([key, horas]) => {
      const idx = key.lastIndexOf("|");
      const wid = key.slice(0, idx);
      const mes = key.slice(idx + 1);
      const [y, m] = mes.split("-");
      return { worker: getWorker(wid)?.nombre || "Trabajador eliminado", mesLabel: `${MESES[Number(m) - 1]} ${y}`, horas, sortKey: mes };
    }).sort((a, b) => a.sortKey.localeCompare(b.sortKey) || a.worker.localeCompare(b.worker));
    downloadCSV(`horas_por_mes_${year}.csv`,
      ["Trabajador", "Mes", "Horas"],
      filas.map(f => [f.worker, f.mesLabel, f.horas.toFixed(2)])
    );
  };

  const filasCliente = visitasAnio.filter(v => v.clienteId === clienteId);
  const totalHorasCliente = filasCliente.reduce((a, v) => a + v.horas, 0);
  const cliente = getClient(clienteId);

  const exportarCliente = () => {
    downloadCSV(`visitas_${(cliente?.nombre || "cliente").replace(/\s+/g, "_")}_${year}.csv`,
      ["Fecha", "Hora inicio", "Hora fin", "Horas", "Cuadrilla", "Resultado", "Observaciones", "Nota trabajador", "Materiales", "Labores"],
      filasCliente.map(v => [v.fecha, v.horaInicio, v.horaFin, v.horas.toFixed(2), v.cuadrilla, v.resultado, v.observaciones, v.nota, v.materiales, v.labores])
    );
  };

  const mesStr = `${year}-${String(month + 1).padStart(2, "0")}`;
  const materialesPorCliente = {};
  data.orders.forEach(o => {
    if (!o.fecha.startsWith(mesStr)) return;
    o.stops.forEach(s => {
      if (!s.materiales || !s.materiales.trim()) return;
      if (!materialesPorCliente[s.clienteId]) materialesPorCliente[s.clienteId] = [];
      materialesPorCliente[s.clienteId].push({ fecha: o.fecha, materiales: s.materiales.trim() });
    });
  });
  const clientesConMateriales = Object.keys(materialesPorCliente)
    .map(cid => ({ clienteId: cid, cliente: getClient(cid)?.nombre || "Cliente eliminado", entradas: materialesPorCliente[cid] }))
    .sort((a, b) => a.cliente.localeCompare(b.cliente));

  const exportarMaterialesMes = () => {
    const filas = [];
    clientesConMateriales.forEach(c => c.entradas.forEach(e => filas.push([c.cliente, fechaEs(e.fecha), e.materiales])));
    downloadCSV(`materiales_${mesStr}.csv`, ["Cliente", "Fecha", "Materiales"], filas);
  };

  return (
    <div>
      <h2 className="gj-h2 gj-no-print">Exportar datos</h2>

      <div className="gj-card gj-no-print">
        <label className="gj-label">Año</label>
        <input className="gj-input" type="number" value={year} onChange={e => setYear(Number(e.target.value))} style={{ maxWidth: 140 }} />
      </div>

      <div className="gj-card gj-no-print">
        <div className="gj-h3">Visitas de mantenimiento del año</div>
        <div style={{ fontSize: 12.5, color: "var(--ink-soft)", marginBottom: 8 }}>{visitasAnio.length} visitas completadas en {year}.</div>
        <button className="gj-btn accent block" onClick={exportarVisitas} disabled={visitasAnio.length === 0}>
          <Download size={14} /> Descargar CSV de visitas
        </button>
      </div>

      <div className="gj-card gj-no-print">
        <div className="gj-h3">Rentabilidad del año</div>
        <div style={{ fontSize: 12.5, color: "var(--ink-soft)", marginBottom: 8 }}>Horas, cuota, coste estimado y beneficio por cliente de mantenimiento en {year}.</div>
        <button className="gj-btn accent block" onClick={exportarRentabilidad} disabled={data.clients.filter(c => c.tipo !== "obra").length === 0}>
          <Download size={14} /> Descargar CSV de rentabilidad
        </button>
      </div>

      <div className="gj-card gj-no-print">
        <div className="gj-h3">Rentabilidad de obras</div>
        <div style={{ fontSize: 12.5, color: "var(--ink-soft)", marginBottom: 8 }}>Presupuesto, horas y beneficio por cada obra (todo su histórico, no por año).</div>
        <button className="gj-btn accent block" onClick={exportarRentabilidadObras} disabled={data.clients.filter(c => c.tipo === "obra").length === 0}>
          <Download size={14} /> Descargar CSV de obras
        </button>
      </div>

      <div className="gj-card gj-no-print">
        <div className="gj-h3">Horas del equipo</div>
        <div style={{ fontSize: 12.5, color: "var(--ink-soft)", marginBottom: 8 }}>Horas invertidas por cada trabajador en {year}, día a día o resumidas por mes.</div>
        <div style={{ display: "flex", gap: 6 }}>
          <button className="gj-btn accent" style={{ flex: 1, justifyContent: "center" }} onClick={exportarHorasDia} disabled={Object.keys(horasPorDiaTrabajador).length === 0}>
            <Download size={14} /> Por día
          </button>
          <button className="gj-btn accent" style={{ flex: 1, justifyContent: "center" }} onClick={exportarHorasMes} disabled={Object.keys(horasPorDiaTrabajador).length === 0}>
            <Download size={14} /> Por mes
          </button>
        </div>
      </div>

      <div className="gj-card gj-no-print">
        <div className="gj-h3">Materiales del mes</div>
        <div className="gj-grid2" style={{ marginBottom: 8 }}>
          <div className="gj-field" style={{ marginBottom: 0 }}>
            <label className="gj-label">Mes</label>
            <select className="gj-select" value={month} onChange={e => setMonth(Number(e.target.value))}>
              {MESES.map((m, i) => <option key={m} value={i}>{m}</option>)}
            </select>
          </div>
          <div className="gj-field" style={{ marginBottom: 0 }}>
            <label className="gj-label">Año</label>
            <input className="gj-input" type="number" value={year} onChange={e => setYear(Number(e.target.value))} />
          </div>
        </div>
        <div style={{ fontSize: 12.5, color: "var(--ink-soft)", marginBottom: 8 }}>
          Solo aparecen los clientes en los que se registraron materiales ese mes.
        </div>
        {clientesConMateriales.length === 0 ? (
          <div className="gj-empty">Sin materiales registrados en {MESES[month]} de {year}.</div>
        ) : (
          <div className="gj-table-wrap" style={{ marginBottom: 8 }}>
            <table className="gj-table">
              <thead><tr><th>Cliente</th><th>Fecha</th><th>Materiales</th></tr></thead>
              <tbody>
                {clientesConMateriales.map(c => c.entradas.map((e, i) => (
                  <tr key={c.clienteId + i}>
                    {i === 0 && <td rowSpan={c.entradas.length} style={{ fontWeight: 600 }}>{c.cliente}</td>}
                    <td>{fechaEs(e.fecha)}</td>
                    <td>{e.materiales}</td>
                  </tr>
                )))}
              </tbody>
            </table>
          </div>
        )}
        <button className="gj-btn accent block" onClick={exportarMaterialesMes} disabled={clientesConMateriales.length === 0}>
          <Download size={14} /> Descargar CSV de materiales
        </button>
      </div>

      <div className="gj-card gj-no-print">
        <div className="gj-h3">Listado anual por cliente</div>
        <div className="gj-field">
          <label className="gj-label">Cliente</label>
          <select className="gj-select" value={clienteId} onChange={e => setClienteId(e.target.value)}>
            {data.clients.map(c => <option key={c.id} value={c.id}>{c.nombre}{c.tipo === "obra" ? " (obra)" : ""}</option>)}
          </select>
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          <button className="gj-btn" style={{ flex: 1, justifyContent: "center" }} onClick={exportarCliente} disabled={filasCliente.length === 0}>
            <Download size={14} /> CSV
          </button>
          <button className="gj-btn primary" style={{ flex: 1, justifyContent: "center" }} onClick={() => window.print()}>
            <Printer size={14} /> Imprimir / PDF
          </button>
        </div>
      </div>

      <div className="gj-card gj-print-area">
        <div style={{ marginBottom: 10 }}>
          <div className="gj-h3" style={{ marginBottom: 2 }}>{cliente?.nombre || "Sin cliente"}</div>
          <div style={{ fontSize: 12, color: "var(--ink-soft)" }}>{cliente?.direccion}</div>
          <div style={{ fontSize: 12.5, marginTop: 4, fontWeight: 600 }}>
            Informe anual {year} · {filasCliente.length} visitas · {fmtHM(totalHorasCliente)} en total
          </div>
        </div>
        <div className="gj-table-wrap">
          <table className="gj-table">
            <thead>
              <tr><th>Fecha</th><th>Horario</th><th>Duración</th><th>Resultado</th><th>Trabajos</th><th>Observaciones / notas</th><th>Materiales</th></tr>
            </thead>
            <tbody>
              {filasCliente.map(v => (
                <tr key={v.fecha + v.horaInicio}>
                  <td>{v.fecha}</td>
                  <td>{v.horaInicio}–{v.horaFin}</td>
                  <td>{fmtHM(v.horas)}</td>
                  <td>{v.resultado}</td>
                  <td>{v.labores || "—"}</td>
                  <td>{[v.observaciones, v.nota].filter(Boolean).join(" · ") || "—"}</td>
                  <td>{v.materiales || "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {filasCliente.length === 0 && <div className="gj-empty">No hay visitas registradas este año para este cliente.</div>}
      </div>
    </div>
  );
}

function PresupuestosView({ data, persist }) {
  const blank = { nombre: "", direccion: "", telefono: "", email: "", importe: "", fecha: todayStr() };
  const [form, setForm] = useState(blank);
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const añadir = () => {
    if (!form.nombre.trim()) return;
    const next = structuredClone(data);
    next.presupuestos = next.presupuestos || [];
    next.presupuestos.push({
      id: uid("prs"), nombre: form.nombre, direccion: form.direccion, telefono: form.telefono, email: form.email,
      importe: Number(form.importe) || 0, fecha: form.fecha, aprobado: false, convertido: false,
    });
    persist(next);
    setForm(blank);
  };

  const aprobar = (id) => {
    const next = structuredClone(data);
    const p = next.presupuestos.find(x => x.id === id);
    p.aprobado = true;
    p.convertido = true;
    const maxOrden = Math.max(0, ...next.clients.filter(c => c.tipo === "obra").map(c => c.orden || 0));
    next.clients.push({
      id: uid("cli"), nombre: p.nombre, direccion: p.direccion, telefono: p.telefono, email: p.email,
      tipo: "obra", cuotaMensual: 0, presupuesto: p.importe, estadoObra: "en_curso",
      personasEstimadas: 0, diasEstimados: 0, fechaInicioPlan: "", orden: maxOrden + 1, activo: true,
    });
    persist(next);
  };

  const eliminar = (id) => {
    if (!confirm("¿Eliminar este presupuesto?")) return;
    const next = structuredClone(data);
    next.presupuestos = next.presupuestos.filter(x => x.id !== id);
    persist(next);
  };

  const pendientes = (data.presupuestos || []).filter(p => !p.convertido);
  const aprobados = (data.presupuestos || []).filter(p => p.convertido);

  return (
    <div>
      <h2 className="gj-h2">Presupuestos</h2>
      <div className="gj-card">
        <div className="gj-h3">Nuevo presupuesto</div>
        <div className="gj-field"><label className="gj-label">Nombre</label><input className="gj-input" value={form.nombre} onChange={e => set("nombre", e.target.value)} placeholder="Nombre del cliente" /></div>
        <div className="gj-field"><label className="gj-label">Dirección</label><input className="gj-input" value={form.direccion} onChange={e => set("direccion", e.target.value)} /></div>
        <div className="gj-grid2">
          <div className="gj-field"><label className="gj-label">Teléfono</label><input className="gj-input" value={form.telefono} onChange={e => set("telefono", e.target.value)} placeholder="34600111222" /></div>
          <div className="gj-field"><label className="gj-label">Email</label><input className="gj-input" value={form.email} onChange={e => set("email", e.target.value)} /></div>
        </div>
        <div className="gj-grid2">
          <div className="gj-field"><label className="gj-label">Importe (€)</label><input className="gj-input" type="number" value={form.importe} onChange={e => set("importe", e.target.value)} placeholder="3000" /></div>
          <div className="gj-field"><label className="gj-label">Fecha</label><input className="gj-input" type="date" value={form.fecha} onChange={e => set("fecha", e.target.value)} /></div>
        </div>
        <button className="gj-btn accent block" onClick={añadir}><Plus size={14} /> Añadir presupuesto</button>
      </div>

      <h3 className="gj-h3">Pendientes de aprobación</h3>
      {pendientes.length === 0 && <div className="gj-card gj-empty">No hay presupuestos pendientes.</div>}
      {pendientes.map(p => (
        <div className="gj-card" key={p.id}>
          <div className="gj-row">
            <div>
              <div style={{ fontWeight: 600 }}>{p.nombre}</div>
              <div style={{ fontSize: 12, color: "var(--ink-soft)" }}>{p.direccion}</div>
              <div style={{ fontSize: 12.5, marginTop: 2, fontWeight: 600 }}>{eur(p.importe)} · {fechaEs(p.fecha)}</div>
            </div>
            <button className="gj-btn ghost" onClick={() => eliminar(p.id)}><Trash2 size={14} color="var(--warn)" /></button>
          </div>
          <label className="gj-row" style={{ marginTop: 8, cursor: "pointer" }}>
            <span style={{ fontSize: 12.5 }}>Marcar como aprobado</span>
            <input type="checkbox" checked={false} onChange={() => aprobar(p.id)} />
          </label>
        </div>
      ))}

      {aprobados.length > 0 && (
        <>
          <h3 className="gj-h3" style={{ marginTop: 12 }}>Aprobados (ya en Trabajos)</h3>
          {aprobados.map(p => (
            <div className="gj-card gj-row" key={p.id} style={{ opacity: 0.7 }}>
              <div style={{ fontWeight: 600 }}>{p.nombre}</div>
              <span className="gj-badge completado">Aprobado</span>
            </div>
          ))}
        </>
      )}
    </div>
  );
}

function TrabajosView({ data, persist, adminRole }) {
  const obras = data.clients.filter(c => c.tipo === "obra").slice().sort((a, b) => (a.orden || 0) - (b.orden || 0));

  const actualizarCampo = (id, campo, valor) => {
    const next = structuredClone(data);
    const c = next.clients.find(x => x.id === id);
    c[campo] = campo === "fechaInicioPlan" ? valor : (Number(valor) || 0);
    persist(next);
  };

  const mover = (id, dir) => {
    const idx = obras.findIndex(o => o.id === id);
    const otro = obras[idx + dir];
    if (!otro) return;
    const next = structuredClone(data);
    const a = next.clients.find(x => x.id === id);
    const b = next.clients.find(x => x.id === otro.id);
    const tmp = a.orden;
    a.orden = b.orden;
    b.orden = tmp;
    persist(next);
  };

  return (
    <div>
      <h2 className="gj-h2">Listado de trabajos</h2>
      {adminRole === "admin1" && (
        <div style={{ fontSize: 12, color: "var(--ink-soft)", marginBottom: 8 }}>
          Puedes cambiar el orden de la lista con las flechas.
        </div>
      )}
      <div className="gj-table-wrap">
        <table className="gj-table">
          <thead>
            <tr><th></th><th>Obra</th><th>Personas</th><th>Días est.</th><th>Inicio previsto</th><th>Estado</th></tr>
          </thead>
          <tbody>
            {obras.map((o, i) => (
              <tr key={o.id}>
                <td>
                  {adminRole === "admin1" && (
                    <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                      <button className="gj-btn ghost" style={{ padding: 2 }} disabled={i === 0} onClick={() => mover(o.id, -1)}><ArrowUp size={12} /></button>
                      <button className="gj-btn ghost" style={{ padding: 2 }} disabled={i === obras.length - 1} onClick={() => mover(o.id, 1)}><ArrowDown size={12} /></button>
                    </div>
                  )}
                </td>
                <td style={{ fontWeight: 600 }}>{o.nombre}</td>
                <td><input className="gj-input" type="number" style={{ width: 56 }} value={o.personasEstimadas || 0} onChange={e => actualizarCampo(o.id, "personasEstimadas", e.target.value)} /></td>
                <td><input className="gj-input" type="number" style={{ width: 56 }} value={o.diasEstimados || 0} onChange={e => actualizarCampo(o.id, "diasEstimados", e.target.value)} /></td>
                <td><input className="gj-input" type="date" style={{ width: 140 }} value={o.fechaInicioPlan || ""} onChange={e => actualizarCampo(o.id, "fechaInicioPlan", e.target.value)} /></td>
                <td><span className={"gj-badge " + (o.estadoObra === "finalizada" ? "completado" : "en_progreso")}>{o.estadoObra === "finalizada" ? "Finalizada" : "En curso"}</span></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {obras.length === 0 && <div className="gj-card gj-empty">Todavía no hay obras. Se añaden desde Clientes o al aprobar un presupuesto.</div>}
    </div>
  );
}

function FestivoForm({ data, persist, adminRole }) {
  const [fecha, setFecha] = useState(todayStr());
  const [tipo, setTipo] = useState("oficial");
  const [nombre, setNombre] = useState("");

  const añadir = () => {
    const afectadas = festivoAfectaObras(data, fecha);
    if (afectadas.length > 0 && adminRole !== "admin1") {
      return;
    }
    const next = structuredClone(data);
    next.festivos = next.festivos || {};
    next.festivos[fecha] = { tipo, nombre: nombre.trim() };
    persist(next);
    setNombre("");
  };

  const quitar = (dateStr) => {
    const next = structuredClone(data);
    delete next.festivos[dateStr];
    persist(next);
  };

  const festivos = Object.entries(data.festivos || {}).sort((a, b) => a[0].localeCompare(b[0]));

  return (
    <div className="gj-card">
      <div className="gj-h3">Días festivos</div>
      <div className="gj-grid2">
        <div className="gj-field"><label className="gj-label">Fecha</label><input className="gj-input" type="date" value={fecha} onChange={e => setFecha(e.target.value)} /></div>
        <div className="gj-field"><label className="gj-label">Tipo</label>
          <select className="gj-select" value={tipo} onChange={e => setTipo(e.target.value)}>
            <option value="oficial">Oficial</option>
            <option value="empresa">Empresa</option>
          </select>
        </div>
      </div>
      <div className="gj-field"><label className="gj-label">Nombre (opcional)</label><input className="gj-input" value={nombre} onChange={e => setNombre(e.target.value)} placeholder="Ej: Día del Pilar" /></div>
      <button className="gj-btn block" onClick={añadir}><PartyPopper size={14} /> Añadir festivo</button>
      {festivos.length > 0 && (
        <div style={{ marginTop: 10 }}>
          {festivos.map(([d, f]) => (
            <div className="gj-row" key={d} style={{ padding: "4px 0", borderBottom: "1px solid var(--line-soft)" }}>
              <span style={{ fontSize: 12.5 }}>{fechaEs(d)} — {f.nombre || (f.tipo === "oficial" ? "Oficial" : "Empresa")} <span className="gj-badge" style={{ background: "var(--pend-bg)", color: "var(--ink-soft)" }}>{f.tipo}</span></span>
              <button className="gj-btn ghost" onClick={() => quitar(d)}><Trash2 size={12} color="var(--warn)" /></button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function CalendarioObrasView({ data, persist, adminRole, requestUnlock, adminMode }) {
  const now = new Date();
  const [year, setYear] = useState(now.getFullYear());
  const [month, setMonth] = useState(now.getMonth());

  const coloresObra = ["#2F4D34", "#C97A2B", "#6B8F3C", "#8E5B9F", "#3E6E8E", "#B4452B"];
  const obras = data.clients.filter(c => c.tipo === "obra" && c.fechaInicioPlan && c.diasEstimados > 0);
  const mapa = {};
  obras.forEach((o, idx) => {
    const color = coloresObra[idx % coloresObra.length];
    calcularDiasObra(o, data.festivos || {}).forEach(d => {
      (mapa[d] = mapa[d] || []).push({ nombre: o.nombre, color });
    });
  });

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const todayKey = todayStr();
  const prevMonth = () => { if (month === 0) { setMonth(11); setYear(y => y - 1); } else setMonth(m => m - 1); };
  const nextMonth = () => { if (month === 11) { setMonth(0); setYear(y => y + 1); } else setMonth(m => m + 1); };

  return (
    <div>
      <div className="gj-row" style={{ marginBottom: 10 }}>
        <h2 className="gj-h2" style={{ margin: 0 }}>Calendario de obras</h2>
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <button className="gj-btn ghost" onClick={prevMonth}><ChevronLeft size={16} /></button>
          <span style={{ fontSize: 13, fontWeight: 600, minWidth: 90, textAlign: "center" }}>{MESES[month]} {year}</span>
          <button className="gj-btn ghost" onClick={nextMonth}><ChevronRight size={16} /></button>
        </div>
      </div>

      {adminMode ? <FestivoForm data={data} persist={persist} adminRole={adminRole} /> : (
        <div className="gj-card gj-row" style={{ background: "var(--pend-bg)" }}>
          <div style={{ fontSize: 12.5, color: "var(--ink-soft)" }}>Entra como administrador para gestionar festivos.</div>
          <button className="gj-btn ghost" onClick={requestUnlock}><Lock size={13} /></button>
        </div>
      )}

      {obras.length > 0 && (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, margin: "10px 0", fontSize: 11.5 }}>
          {obras.map((o, idx) => (
            <span key={o.id} style={{ display: "flex", alignItems: "center", gap: 4 }}>
              <span style={{ width: 10, height: 10, borderRadius: "50%", background: coloresObra[idx % coloresObra.length], display: "inline-block" }} />
              {o.nombre}
            </span>
          ))}
        </div>
      )}

      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 4 }}>
        {days.map(d => {
          const dateStr = `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
          const entradas = mapa[dateStr] || [];
          const festivo = (data.festivos || {})[dateStr];
          let background = "#fff";
          if (festivo) background = "repeating-linear-gradient(45deg, #ccc, #ccc 4px, #e2e2e2 4px, #e2e2e2 8px)";
          else if (entradas.length === 1) background = entradas[0].color;
          else if (entradas.length > 1) {
            const pct = 100 / entradas.length;
            background = "linear-gradient(135deg, " + entradas.map((e, i) => `${e.color} ${i * pct}%, ${e.color} ${(i + 1) * pct}%`).join(", ") + ")";
          }
          const esBlanco = entradas.length > 0 || festivo;
          return (
            <div key={d}
              title={festivo ? (festivo.nombre || festivo.tipo) : entradas.map(e => e.nombre).join(", ")}
              style={{
                aspectRatio: "1", borderRadius: 4, border: "1px solid var(--line-soft)",
                display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11,
                background, color: esBlanco ? "#fff" : "var(--ink)",
                fontWeight: dateStr === todayKey ? 700 : 400,
                boxShadow: dateStr === todayKey ? "0 0 0 1.5px var(--accent) inset" : "none",
                textShadow: esBlanco && !festivo ? "0 1px 1px rgba(0,0,0,.3)" : "none",
              }}>
              {d}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function MapaView({ data, persist, focusClienteId, setFocusClienteId }) {
  const mapRef = useRef(null);
  const mapInstance = useRef(null);
  const markersRef = useRef({});
  const [leafletReady, setLeafletReady] = useState(!!window.L);
  const [leafletError, setLeafletError] = useState(false);
  const [retryTick, setRetryTick] = useState(0);
  const [geocodando, setGeocodando] = useState(false);

  // Cargar Leaflet (mapa) una sola vez
  useEffect(() => {
    if (window.L) { setLeafletReady(true); return; }
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
    document.head.appendChild(link);
    const urls = [
      "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js",
      "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.js",
      "https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js",
    ];
    const tryLoad = (i) => {
      if (i >= urls.length) { setLeafletError(true); return; }
      const s = document.createElement("script");
      s.src = urls[i];
      s.onload = () => setLeafletReady(true);
      s.onerror = () => tryLoad(i + 1);
      document.head.appendChild(s);
    };
    tryLoad(0);
  }, []);

  // Inicializar el mapa centrado en Navarra
  useEffect(() => {
    if (!leafletReady || !mapRef.current || mapInstance.current) return;
    const L = window.L;
    delete L.Icon.Default.prototype._getIconUrl;
    L.Icon.Default.mergeOptions({
      iconRetinaUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png",
      iconUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png",
      shadowUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png",
    });
    const map = L.map(mapRef.current);
    map.fitBounds([[42.775, -1.665], [42.845, -1.545]], { padding: [15, 15] });
    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      attribution: "&copy; colaboradores de OpenStreetMap",
      maxZoom: 19,
    }).addTo(map);
    mapInstance.current = map;
  }, [leafletReady]);

  // Geocodificar automáticamente las direcciones de los clientes que aún no tengan coordenadas
  useEffect(() => {
    let cancelled = false;
    async function geocodeAll() {
      let working = structuredClone(data);
      const pendientes = working.clients.filter(c => !c.lat && !c.geocodeFailed && c.direccion);
      if (pendientes.length === 0) return;
      setGeocodando(true);
      for (const c of pendientes) {
        if (cancelled) break;
        try {
          const url = `https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=es&viewbox=-2.65,43.35,-0.75,41.75&bounded=0&q=${encodeURIComponent(c.direccion)}`;
          const res = await fetch(url, { headers: { "Accept-Language": "es" } });
          const json = await res.json();
          const cc = working.clients.find(x => x.id === c.id);
          if (json && json[0]) {
            cc.lat = parseFloat(json[0].lat);
            cc.lng = parseFloat(json[0].lon);
          } else {
            cc.geocodeFailed = true;
          }
        } catch (e) {
          // sin conexión o fallo puntual: se reintentará en la próxima visita a esta pestaña
        }
        persist(structuredClone(working));
        await new Promise(r => setTimeout(r, 1100));
      }
      if (!cancelled) setGeocodando(false);
    }
    geocodeAll();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [data.clients.length, retryTick]);

  // Pintar/actualizar los marcadores cuando cambien los clientes localizados
  useEffect(() => {
    if (!mapInstance.current || !window.L) return;
    Object.values(markersRef.current).forEach(m => mapInstance.current.removeLayer(m));
    markersRef.current = {};
    data.clients.filter(c => c.lat && c.lng).forEach(c => {
      const marker = window.L.marker([c.lat, c.lng]).addTo(mapInstance.current);
      const safeName = c.nombre.replace(/</g, "&lt;");
      const safeAddr = c.direccion.replace(/</g, "&lt;");
      marker.bindPopup(
        `<b>${safeName}${c.tipo === "obra" ? " (obra)" : ""}</b><br>${safeAddr}<br><a href="${mapsLink(c.direccion)}" target="_blank" rel="noreferrer">Cómo llegar →</a>`
      );
      markersRef.current[c.id] = marker;
    });
  }, [leafletReady, data.clients]);

  // Si venimos desde "Ver en el mapa" de un cliente concreto, centrar y abrir su ficha
  useEffect(() => {
    if (!focusClienteId || !mapInstance.current) return;
    const c = data.clients.find(x => x.id === focusClienteId);
    if (!c) { setFocusClienteId(null); return; }
    if (c.lat && c.lng) {
      mapInstance.current.setView([c.lat, c.lng], 15);
      const marker = markersRef.current[c.id];
      if (marker) marker.openPopup();
      setFocusClienteId(null);
    }
    // si aún no tiene coordenadas (se está geocodificando), esperamos a que aparezcan en data.clients
  }, [focusClienteId, data.clients, leafletReady]);

  const localizados = data.clients.filter(c => c.lat && c.lng).length;
  const fallidos = data.clients.filter(c => c.geocodeFailed).length;
  const total = data.clients.length;

  const reintentar = () => {
    const next = structuredClone(data);
    next.clients.forEach(c => { delete c.geocodeFailed; });
    persist(next);
    setRetryTick(t => t + 1);
  };

  return (
    <div>
      <h2 className="gj-h2">Mapa de clientes</h2>
      <div style={{ fontSize: 12, color: "var(--ink-soft)", marginBottom: 8 }}>
        Los indicadores se generan automáticamente a partir de las direcciones ya dadas de alta en Clientes — no hace falta introducirlas a mano. Vista inicial centrada en Pamplona y la Cuenca, incluyendo Sarriguren, Gorraiz y Olloki.
      </div>

      {leafletError && (
        <div className="gj-card" style={{ background: "var(--warn-bg)", color: "var(--warn)" }}>
          No se ha podido cargar el mapa (revisa la conexión a internet). El resto de la app sigue funcionando con normalidad.
        </div>
      )}

      {!leafletError && (
        <>
          <div className="gj-map" ref={mapRef}></div>
          <div className="gj-row" style={{ marginTop: 8 }}>
            <div style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              {localizados} de {total} clientes localizados en el mapa
              {geocodando && " · localizando direcciones..."}
              {fallidos > 0 && ` · ${fallidos} sin localizar`}
            </div>
            {fallidos > 0 && <button className="gj-btn ghost" onClick={reintentar}>Reintentar</button>}
          </div>
        </>
      )}
      {data.clients.length === 0 && <div className="gj-card gj-empty" style={{ marginTop: 10 }}>Añade clientes con dirección para verlos aquí.</div>}
    </div>
  );
}

function CalendarioView({ data, persist, getClient, adminMode, adminRole, requestUnlock }) {
  const now = new Date();
  const [year, setYear] = useState(now.getFullYear());
  const [month, setMonth] = useState(now.getMonth());

  const autoMarks = {};
  data.orders.forEach(o => {
    o.stops.forEach(s => {
      if (s.estado === "completado") autoMarks[s.clienteId + "|" + o.fecha] = true;
    });
  });

  const isDone = (key) => (key in data.calendarManual ? data.calendarManual[key] : !!autoMarks[key]);

  const ultimaVisitaPorCliente = {};
  const todasLasClaves = new Set([...Object.keys(autoMarks), ...Object.keys(data.calendarManual)]);
  todasLasClaves.forEach(key => {
    if (!isDone(key)) return;
    const idx = key.lastIndexOf("|");
    const cid = key.slice(0, idx);
    const dateStr = key.slice(idx + 1);
    if (!ultimaVisitaPorCliente[cid] || dateStr > ultimaVisitaPorCliente[cid]) {
      ultimaVisitaPorCliente[cid] = dateStr;
    }
  });

  const toggleMark = (clienteId, dateStr) => {
    if (!adminMode) return;
    const key = clienteId + "|" + dateStr;
    const next = structuredClone(data);
    next.calendarManual[key] = !isDone(key);
    persist(next);
  };

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const todayKey = todayStr();

  const prevMonth = () => { if (month === 0) { setMonth(11); setYear(y => y - 1); } else setMonth(m => m - 1); };
  const nextMonth = () => { if (month === 11) { setMonth(0); setYear(y => y + 1); } else setMonth(m => m + 1); };

  return (
    <div>
      <div className="gj-row" style={{ marginBottom: 10 }}>
        <h2 className="gj-h2" style={{ margin: 0 }}>Calendario</h2>
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <button className="gj-btn ghost" onClick={prevMonth}><ChevronLeft size={16} /></button>
          <span style={{ fontSize: 13, fontWeight: 600, minWidth: 90, textAlign: "center" }}>{MESES[month]} {year}</span>
          <button className="gj-btn ghost" onClick={nextMonth}><ChevronRight size={16} /></button>
        </div>
      </div>
      {adminMode ? (
        <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginBottom: 8 }}>
          Toca un día para marcarlo o quitarlo, aunque ya venga marcado por el fichaje de un trabajador (útil si se equivocaron al fichar). El día en <span style={{ color: "var(--highlight-ink)", fontWeight: 600 }}>ámbar</span> es la última visita registrada de cada cliente.
        </div>
      ) : (
        <div>
          <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginBottom: 4 }}>
            El día en <span style={{ color: "var(--highlight-ink)", fontWeight: 600 }}>ámbar</span> es la última visita registrada de cada cliente.
          </div>
          <div className="gj-card gj-row" style={{ background: "var(--pend-bg)", marginBottom: 8, padding: 10 }}>
            <div style={{ fontSize: 12.5, color: "var(--ink-soft)" }}>Solo un administrador puede añadir o quitar visitas en este calendario.</div>
            <button className="gj-btn ghost" onClick={requestUnlock}><Lock size={13} /></button>
          </div>
        </div>
      )}
      {adminMode && <FestivoForm data={data} persist={persist} adminRole={adminRole} />}
      <div className="gj-table-wrap">
        <table className="gj-table">
          <thead>
            <tr>
              <th style={{ position: "sticky", left: 0, background: "var(--bg)" }}>Cliente</th>
              {days.map(d => {
                const dStr = `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
                const esFestivo = (data.festivos || {})[dStr];
                return <th key={d} style={{ textAlign: "center", background: esFestivo ? "var(--pend-bg)" : undefined }} title={esFestivo ? (esFestivo.nombre || esFestivo.tipo) : ""}>{d}</th>;
              })}
            </tr>
          </thead>
          <tbody>
            {data.clients.map(c => (
              <tr key={c.id}>
                <td style={{ fontWeight: 600, position: "sticky", left: 0, background: "var(--surface)" }}>{c.nombre}{c.tipo === "obra" ? " (obra)" : ""}</td>
                {days.map(d => {
                  const dateStr = `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
                  const key = c.id + "|" + dateStr;
                  const done = isDone(key);
                  const esUltima = done && ultimaVisitaPorCliente[c.id] === dateStr;
                  return (
                    <td key={d} style={{ textAlign: "center" }}>
                      <div className={"gj-daycell" + (esUltima ? " latest" : done ? " done" : "") + (dateStr === todayKey ? " today" : "")}
                        style={{ cursor: adminMode ? "pointer" : "default" }}
                        onClick={() => toggleMark(c.id, dateStr)}>
                        {done ? <CheckCircle2 size={13} /> : ""}
                      </div>
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {data.clients.length === 0 && <div className="gj-card gj-empty">Añade clientes para verlos aquí.</div>}
    </div>
  );
}

function RentabilidadView({ data, persist }) {
  const [year, setYear] = useState(new Date().getFullYear());
  const [costeHora, setCosteHora] = useState(data.settings.costeHora);
  const [nuevoPin1, setNuevoPin1] = useState("");
  const [nuevoPin2, setNuevoPin2] = useState("");
  const [nombreAdmin1, setNombreAdmin1] = useState(data.settings.adminNombre1 || "Rafa");
  const [nombreAdmin2, setNombreAdmin2] = useState(data.settings.adminNombre2 || "Gonzalo");
  const [almuerzoMin, setAlmuerzoMin] = useState(data.settings.almuerzoEstandarMin || 15);

  const guardarCoste = () => {
    const next = structuredClone(data);
    next.settings.costeHora = Number(costeHora) || 0;
    persist(next);
  };

  const guardarAlmuerzo = () => {
    const next = structuredClone(data);
    next.settings.almuerzoEstandarMin = Number(almuerzoMin) || 0;
    persist(next);
  };

  const guardarPin1 = () => {
    if (!nuevoPin1.trim()) return;
    const next = structuredClone(data);
    next.settings.adminPin1 = nuevoPin1.trim();
    persist(next);
    setNuevoPin1("");
  };
  const guardarPin2 = () => {
    if (!nuevoPin2.trim()) return;
    const next = structuredClone(data);
    next.settings.adminPin2 = nuevoPin2.trim();
    persist(next);
    setNuevoPin2("");
  };
  const guardarNombreAdmin1 = () => {
    const next = structuredClone(data);
    next.settings.adminNombre1 = nombreAdmin1.trim() || "Administrador 1";
    persist(next);
  };
  const guardarNombreAdmin2 = () => {
    const next = structuredClone(data);
    next.settings.adminNombre2 = nombreAdmin2.trim() || "Administrador 2";
    persist(next);
  };

  const filas = data.clients.filter(c => c.tipo !== "obra").map(c => {
    let horasPersona = 0;
    data.orders.forEach(o => {
      if (!o.fecha.startsWith(String(year))) return;
      o.stops.forEach(s => {
        if (s.clienteId === c.id && s.estado === "completado") {
          horasPersona += diffHours(s.horaInicio, s.horaFin) * (s.crewSize || o.workerIds.length);
        }
      });
    });
    const cuotaAnual = c.cuotaMensual * 12;
    const costeAnual = horasPersona * (Number(costeHora) || 0);
    const beneficio = cuotaAnual - costeAnual;
    const margen = cuotaAnual > 0 ? (beneficio / cuotaAnual) * 100 : 0;
    return { c, horasPersona, cuotaAnual, costeAnual, beneficio, margen };
  });

  const totalHoras = filas.reduce((a, f) => a + f.horasPersona, 0);
  const totalBeneficio = filas.reduce((a, f) => a + f.beneficio, 0);
  const totalCuota = filas.reduce((a, f) => a + f.cuotaAnual, 0);

  return (
    <div>
      <h2 className="gj-h2">Rentabilidad</h2>
      <div style={{ fontSize: 12, color: "var(--ink-soft)", marginBottom: 8 }}>Solo incluye clientes de mantenimiento (los de obras se facturan por presupuesto, no por cuota).</div>
      <div className="gj-card">
        <div className="gj-grid2">
          <div className="gj-field"><label className="gj-label">Año</label>
            <input className="gj-input" type="number" value={year} onChange={e => setYear(Number(e.target.value))} />
          </div>
          <div className="gj-field"><label className="gj-label">Coste estimado por hora-persona (€)</label>
            <div style={{ display: "flex", gap: 6 }}>
              <input className="gj-input" type="number" value={costeHora} onChange={e => setCosteHora(e.target.value)} />
              <button className="gj-btn" onClick={guardarCoste}>Guardar</button>
            </div>
          </div>
        </div>
        <div className="gj-field"><label className="gj-label">Tiempo estándar de almuerzo (minutos)</label>
          <div style={{ display: "flex", gap: 6 }}>
            <input className="gj-input" type="number" value={almuerzoMin} onChange={e => setAlmuerzoMin(e.target.value)} />
            <button className="gj-btn" onClick={guardarAlmuerzo}>Guardar</button>
          </div>
          <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginTop: 4 }}>Este valor aparece ya rellenado en Fichar cuando una cuadrilla crea su jornada, aunque pueden ajustarlo ese día si hiciera falta.</div>
        </div>
        <hr className="gj-divider" />
        <div className="gj-field"><label className="gj-label">Nombre del Administrador 1</label>
          <div style={{ display: "flex", gap: 6 }}>
            <input className="gj-input" value={nombreAdmin1} onChange={e => setNombreAdmin1(e.target.value)} placeholder="Rafa" />
            <button className="gj-btn" onClick={guardarNombreAdmin1}>Guardar</button>
          </div>
        </div>
        <div className="gj-field"><label className="gj-label">Cambiar PIN de Administrador 1 ({data.settings.adminNombre1 || "Rafa"})</label>
          <div style={{ display: "flex", gap: 6 }}>
            <input className="gj-input" value={nuevoPin1} onChange={e => setNuevoPin1(e.target.value)} placeholder="Nuevo PIN admin 1" />
            <button className="gj-btn" onClick={guardarPin1}>Guardar</button>
          </div>
        </div>
        <div className="gj-field"><label className="gj-label">Nombre del Administrador 2</label>
          <div style={{ display: "flex", gap: 6 }}>
            <input className="gj-input" value={nombreAdmin2} onChange={e => setNombreAdmin2(e.target.value)} placeholder="Gonzalo" />
            <button className="gj-btn" onClick={guardarNombreAdmin2}>Guardar</button>
          </div>
        </div>
        <div className="gj-field"><label className="gj-label">Cambiar PIN de Administrador 2 ({data.settings.adminNombre2 || "Gonzalo"})</label>
          <div style={{ display: "flex", gap: 6 }}>
            <input className="gj-input" value={nuevoPin2} onChange={e => setNuevoPin2(e.target.value)} placeholder="Nuevo PIN admin 2" />
            <button className="gj-btn" onClick={guardarPin2}>Guardar</button>
          </div>
        </div>
      </div>

      <div className="gj-grid2" style={{ marginBottom: 12 }}>
        <div className="gj-stat"><div className="n">{fmtHM(totalHoras)}</div><div className="l">Horas-persona en {year}</div></div>
        <div className="gj-stat"><div className="n">{eur(totalBeneficio)}</div><div className="l">Beneficio estimado {year} (sobre {eur(totalCuota)} facturado)</div></div>
      </div>

      <div className="gj-table-wrap">
        <table className="gj-table">
          <thead>
            <tr>
              <th>Cliente</th><th>Horas-persona</th><th>Cuota anual</th><th>Coste est.</th><th>Beneficio</th><th>Margen</th>
            </tr>
          </thead>
          <tbody>
            {filas.map(f => (
              <tr key={f.c.id}>
                <td style={{ fontWeight: 600 }}>{f.c.nombre}</td>
                <td>{fmtHM(f.horasPersona)}</td>
                <td>{eur(f.cuotaAnual)}</td>
                <td>{eur(f.costeAnual)}</td>
                <td style={{ color: f.beneficio >= 0 ? "var(--good)" : "var(--warn)", fontWeight: 600 }}>{eur(f.beneficio)}</td>
                <td>{f.margen.toFixed(0)}%</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {data.clients.length === 0 && <div className="gj-card gj-empty">Añade clientes para ver su rentabilidad.</div>}
    </div>
  );
}

function RentabilidadObrasView({ data, persist }) {
  const obras = data.clients.filter(c => c.tipo === "obra");
  const costeHora = Number(data.settings.costeHora) || 0;

  const filas = obras.map(c => {
    let horasPersona = 0;
    let primera = null, ultima = null;
    const materiales = [];
    data.orders.forEach(o => {
      o.stops.forEach(s => {
        if (s.clienteId === c.id && s.estado === "completado") {
          horasPersona += diffHours(s.horaInicio, s.horaFin) * (s.crewSize || o.workerIds.length);
          if (!primera || o.fecha < primera) primera = o.fecha;
          if (!ultima || o.fecha > ultima) ultima = o.fecha;
        }
        if (s.clienteId === c.id && s.materiales && s.materiales.trim()) {
          materiales.push({ fecha: o.fecha, materiales: s.materiales.trim() });
        }
      });
    });
    const costeEstimado = horasPersona * costeHora;
    const beneficio = c.presupuesto - costeEstimado;
    const margen = c.presupuesto > 0 ? (beneficio / c.presupuesto) * 100 : 0;
    return { c, horasPersona, costeEstimado, beneficio, margen, primera, ultima, materiales };
  });

  const totalPresupuesto = filas.reduce((a, f) => a + f.c.presupuesto, 0);
  const totalCoste = filas.reduce((a, f) => a + f.costeEstimado, 0);
  const totalBeneficio = filas.reduce((a, f) => a + f.beneficio, 0);

  return (
    <div>
      <h2 className="gj-h2">Rentabilidad de obras</h2>
      <div style={{ fontSize: 12, color: "var(--ink-soft)", marginBottom: 8 }}>
        Solo clientes de obras. Se calcula sobre el presupuesto total del proyecto, no por año — usa el coste por hora-persona configurado en Rentabilidad ({eur(costeHora)}/h).
      </div>

      <div className="gj-grid2" style={{ marginBottom: 12 }}>
        <div className="gj-stat"><div className="n">{eur(totalPresupuesto)}</div><div className="l">Presupuesto total</div></div>
        <div className="gj-stat"><div className="n">{eur(totalBeneficio)}</div><div className="l">Beneficio estimado (coste: {eur(totalCoste)})</div></div>
      </div>

      <div className="gj-table-wrap">
        <table className="gj-table">
          <thead>
            <tr>
              <th>Obra</th><th>Estado</th><th>Horas-persona</th><th>Presupuesto</th><th>Coste est.</th><th>Beneficio</th><th>Margen</th>
            </tr>
          </thead>
          <tbody>
            {filas.map(f => (
              <tr key={f.c.id}>
                <td style={{ fontWeight: 600 }}>
                  {f.c.nombre}
                  {f.primera && <div style={{ fontSize: 11, color: "var(--ink-soft)", fontWeight: 400 }}>{fechaEs(f.primera)}{f.ultima !== f.primera ? " – " + fechaEs(f.ultima) : ""}</div>}
                </td>
                <td><span className={"gj-badge " + (f.c.estadoObra === "finalizada" ? "completado" : "en_progreso")}>{f.c.estadoObra === "finalizada" ? "Finalizada" : "En curso"}</span></td>
                <td>{fmtHM(f.horasPersona)}</td>
                <td>{eur(f.c.presupuesto)}</td>
                <td>{eur(f.costeEstimado)}</td>
                <td style={{ color: f.beneficio >= 0 ? "var(--good)" : "var(--warn)", fontWeight: 600 }}>{eur(f.beneficio)}</td>
                <td>{f.margen.toFixed(0)}%</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {obras.length === 0 && <div className="gj-card gj-empty">Todavía no hay clientes de obras dados de alta.</div>}

      <h3 className="gj-h3" style={{ marginTop: 12 }}>Materiales utilizados por obra</h3>
      {filas.filter(f => f.materiales.length > 0).length === 0 ? (
        <div className="gj-card gj-empty">Todavía no se han registrado materiales en ninguna obra.</div>
      ) : (
        filas.filter(f => f.materiales.length > 0).map(f => (
          <div className="gj-card" key={f.c.id}>
            <div style={{ fontWeight: 600, marginBottom: 4 }}>{f.c.nombre}</div>
            {f.materiales.map((m, i) => (
              <div key={i} style={{ fontSize: 12.5, marginBottom: 2 }}>
                <span style={{ color: "var(--ink-soft)" }}>{fechaEs(m.fecha)} —</span> {m.materiales}
              </div>
            ))}
          </div>
        ))
      )}
      {filas.some(f => f.materiales.length > 0) && (
        <button className="gj-btn accent block" onClick={() => {
          const rows = [];
          filas.forEach(f => f.materiales.forEach(m => rows.push([f.c.nombre, fechaEs(m.fecha), m.materiales])));
          downloadCSV("materiales_obras.csv", ["Obra", "Fecha", "Materiales"], rows);
        }}>
          <Download size={14} /> Descargar CSV de materiales de obras
        </button>
      )}
    </div>
  );
}
